window.ATTIVITA = [
  {"nome": "Conversazione in 4 fasi", "modulo": "Attività pratiche – Famiglie", "durata": "Non specificata", "target": "Adulti (genitori/tutori); target indiretto: bambini e adolescenti 9-18 anni", "obiettivo": "Supportare i genitori nel prepararsi e avviare una conversazione su sesso, sessualità e pornografia con i propri figli", "materiali": "Dossier CONSENT; bibliografia consigliata", "partecipanti": "Individuale o coppia genitoriale", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "Attività strutturata in 4 fasi progressive. 1ª fase: il genitore legge il dossier CONSENT e la bibliografia per acquisire conoscenze. 2ª fase: riflessione personale su proprie concezioni di sesso e sessualità, esperienze pregresse, valori da trasmettere. 3ª fase: creare un ambiente sicuro scegliendo un contesto informale (in macchina, cucinando), garantire l'intimità, approcciare con empatia, evitare di mostrare rabbia se il figlio ha visto materiale pornografico. 4ª fase: avviare la conversazione in modo indiretto partendo dall'uso di Internet e social network; usare spunti quotidiani (film, serie, pubblicità); adattare i contenuti all'età (9-12 anni: limiti, privacy, consenso, dispositivi; 13-18 anni: salute, relazioni, mascolinità tossica, pornografia, sexting).", "tag": "sessualità; comunicazione; emozioni e benessere"},
  {"nome": "Misurare la temperatura", "modulo": "Attività pratiche – Famiglie", "durata": "Non specificata", "target": "Adulti (genitori/tutori); target indiretto: preadolescenti e adolescenti", "obiettivo": "Valutare le conoscenze e le esperienze pregresse del figlio sulla sessualità prima di avviare una conversazione diretta", "materiali": "Elenco di domande guida (fornito nel manuale)", "partecipanti": "Individuale (genitore con figlio/a)", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "Il genitore non dà per scontato che il figlio abbia già visto pornografia e pone domande preliminari: dove/come ha imparato ciò che sa sulla sessualità; cosa pensa dovrebbero sapere i coetanei; quali argomenti lo interessano; con chi può parlare di sessualità; se ha mai visto materiale pornografico; cosa ne ha appreso; come si è sentito guardandolo; se pensa che la pornografia abbia lasciato segni su di sé o sugli altri. Le risposte permettono di calibrare il tono della conversazione successiva.", "tag": "sessualità; comunicazione; pornografia"},
  {"nome": "Zone del corpo: il semaforo", "modulo": "Attività pratiche – Famiglie", "durata": "Non specificata", "target": "Adulti (genitori/tutori) con bambini; adattabile per fasce d'età diverse", "obiettivo": "Educare bambini e ragazzi al consenso e ai limiti corporei", "materiali": "Disegno schematico del corpo umano (stampato o su tablet); pennarelli o penne in tre colori (rosso, giallo, verde)", "partecipanti": "Individuale (genitore con figlio/a) o piccolo gruppo", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "Il genitore consegna al figlio il disegno di un corpo umano e tre pennarelli. Codice colore: rosso = non va bene/non toccare; giallo = forse, meglio chiedere; verde = generalmente ok. Il figlio colora le parti del corpo riflettendo su chi può toccarle, in che modo e come ci si sente. Il genitore compie la stessa attività su un proprio disegno. Si condividono poi le riflessioni sottolineando l'importanza del dialogo aperto sui limiti come forma di rispetto. Domande guida: che tipo di contatto può avvenire in quella zona? Ti hanno mai toccato lì? È comune tra i tuoi amici?", "tag": "contatto fisico; consenso; comunicazione"},
  {"nome": "Misurare la temperatura", "modulo": "Attività pratiche – Insegnanti", "durata": "Non specificata", "target": "Insegnanti ed educatori; target indiretto: bambini e adolescenti", "obiettivo": "Valutare le conoscenze e le esperienze pregresse degli studenti sulla sessualità prima di affrontare la pornografia in classe", "materiali": "Elenco di domande guida (fornito nel manuale)", "partecipanti": "Intera classe o piccoli gruppi", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "Identica nella struttura alla versione per famiglie ma condotta dall'insegnante in contesto scolastico. L'insegnante non dà per scontato che gli studenti abbiano già visto pornografia e introduce l'argomento tramite domande preliminari: dove/come hanno imparato ciò che sanno sulla sessualità; cosa ritengono dovrebbero sapere i coetanei; quali temi li interessano; con chi possono parlare; se hanno mai visto materiale pornografico; cosa ne hanno appreso; come si sono sentiti; se pensano che la pornografia abbia lasciato segni su di sé o sugli altri. Le risposte orientano la progettazione degli interventi successivi.", "tag": "sessualità; comunicazione; pornografia"},
  {"nome": "Il messaggio nascosto dei media", "modulo": "Attività pratiche – Insegnanti", "durata": "30 minuti", "target": "Adolescenti (studenti scuola secondaria)", "obiettivo": "Far riflettere sull'oggettivazione e l'ipersessualizzazione di donne e ragazze nei media e sul suo impatto sulla visione della donna nella società", "materiali": "Immagini pubblicitarie selezionate dall'insegnante; fogli per annotazioni", "partecipanti": "Gruppi misti di 4-5 persone", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante divide la classe in gruppi misti (maschi e femmine insieme) e assegna a ciascuno una o più immagini pubblicitarie. Fase di lavoro in gruppo (10 min.): osservare e discutere le immagini, riflettendo su quale messaggio comunicano, cosa dicono sugli uomini e sulle donne, annotare le riflessioni. Condivisione in plenaria (15 min.): ogni gruppo presenta le proprie osservazioni. L'insegnante facilita la discussione sul legame tra pubblicità, sessualizzazione, norme di genere e cultura pornografica.", "tag": "pornografia; genere e stereotipi; sessualità"},
  {"nome": "Che cosa è violenza?", "modulo": "Attività pratiche – Insegnanti", "durata": "30 minuti", "target": "Adolescenti (studenti scuola secondaria)", "obiettivo": "Far riflettere su concetti normalizzati dalla pornografia che rappresentano forme di violenza", "materiali": "Foglio con le parole chiave: SVALUTARE, DISCRIMINARE, UMILIARE, OGGETTIVIZZARE, DISUMANIZZARE, NORMALIZZARE; materiale per annotazioni", "partecipanti": "Gruppi di 4-5 persone con uguale numero di partecipanti", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante divide la classe in gruppi di 4-5 persone e consegna un foglio con sei parole chiave. Fase di lavoro (15 min.): ogni gruppo trova esempi concreti tratti dalla pornografia per ciascuna parola, ragionando su come questi concetti – non immediatamente associati alla violenza – siano al cuore dell'industria pornografica. Condivisione in plenaria (10 min.): ogni gruppo presenta i propri esempi aprendo la discussione collettiva.", "tag": "pornografia; violenza di genere; genere e stereotipi"},
  {"nome": "Vincitori e perdenti nella pornografia", "modulo": "Attività pratiche – Insegnanti", "durata": "30 minuti", "target": "Adolescenti (studenti scuola secondaria)", "obiettivo": "Riflettere su chi trae vantaggio e chi subisce danni dalla produzione e diffusione di materiale pornografico", "materiali": "Fogli bianchi divisi in due colonne (vincitori/perdenti); lavagna", "partecipanti": "Coppie di studenti; condivisione in plenaria", "fonte": "CONSENT – Manuale di formazione per famiglie e insegnanti (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante divide la classe in coppie. Ogni coppia (10 min.) discute e individua vincitori e perdenti nell'industria pornografica annotando su un foglio diviso in due colonne. Condivisione a turni in plenaria con brainstorming sulla lavagna (15 min.): ogni gruppo contribuisce con un'idea. L'insegnante stimola la riflessione: perché pensi che siano vincitori/perdenti? Esistono altri collettivi colpiti non ancora nominati? L'obiettivo è considerare l'intera filiera della pornografia e i suoi impatti differenziati.", "tag": "pornografia; violenza di genere"},
  {"nome": "Costruire uno spazio aperto sicuro", "modulo": "Kit scuole primarie – Modulo 1", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni (5ª elementare e 1ª media); gestita da insegnanti", "obiettivo": "Creare il setting appropriato per il programma e stabilire un ambiente condiviso in cui sia possibile parlare apertamente di sessualità ponendo limiti agli atteggiamenti dannosi", "materiali": "Nessuno specifico (possibile tabella 'Cosa sappiamo / Cosa vogliamo sapere' da proiettare o scrivere)", "partecipanti": "Intera classe in cerchio", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "L'attività si svolge in cerchio per favorire il dialogo. Passi: 1. L'insegnante spiega gli obiettivi del programma (parlare di sesso, sessualità, corpo, immagini che si trovano online) senza giudicare le esperienze personali ma aumentando il pensiero critico. 2. Anticipa le possibili emozioni (vergogna, piacere, curiosità, disagio) e normalizza le risposte diverse. 3. Chiede a chi parla di esperienze personali di rispettare la privacy altrui. 4. Chiede agli studenti di scrivere un valore o atteggiamento che vorrebbero vedere nel gruppo per sentirsi a proprio agio. Messaggio chiave: nessuna vergogna e nessuna colpa. Opzionale: tabella KWL (cosa sappiamo / cosa vogliamo sapere) a cui tornare alla fine del programma.", "tag": "comunicazione; emozioni e benessere; sessualità"},
  {"nome": "Emozioni legate alla sessualità", "modulo": "Kit scuole primarie – Modulo 2", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Inquadrare i tabù della sessualità e offrire strumenti per capire perché la sessualità è accompagnata da vergogna, disagio e anche emozioni piacevoli", "materiali": "Emoticon stampate o proiettate; bigliettini", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante mostra delle emoticon e chiede agli studenti di scrivere su bigliettini quali stati d'animo connettono alla sessualità. Raccoglie le emozioni nominandole e riflettendo su di esse con domande. Presenta poi cosa fare quando si manifestano emozioni spiacevoli, suggerendo alternative e incoraggiando la comunicazione emotiva. Messaggio chiave: raccogliere le emozioni enfatizzandone la diversità e validandole tutte. È naturale provare emozioni molto diverse riguardo alla sessualità.", "tag": "emozioni e benessere; sessualità; comunicazione"},
  {"nome": "Un universo di corpi", "modulo": "Kit scuole primarie – Modulo 3: Esplorare il corpo", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Promuovere una visione positiva della diversità dei corpi e sviluppare un pensiero critico sugli standard di bellezza e sulla pressione estetica", "materiali": "Fogli per disegnare; penne; immagini di corpi non normativi da mostrare come alternativa", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Ogni studente disegna un corpo umano guidato dall'insegnante che nomina le parti del corpo. I disegni vengono messi insieme e si chiede cosa hanno in comune i corpi disegnati. L'insegnante guida la riflessione su categorie (colore della pelle, tipo di petto, forma dei genitali, peli) sottolineando come l'immaginario generi corpi normativi che tralasciano molte caratteristiche. Mostra poi immagini di corpi alternativi. Messaggio chiave: non esistono due corpi uguali e tutti sono validi; la diversità è naturale. Libro consigliato: Ama il tuo corpo di Bel Olid.", "tag": "genere e stereotipi; emozioni e benessere; contatto fisico"},
  {"nome": "Tutti i corpi sentono allo stesso modo?", "modulo": "Kit scuole primarie – Modulo 3: Esplorare il corpo", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Far capire che ogni corpo funziona in modo diverso e ha una sensibilità diversa, con elementi di base generalizzabili a tutte le persone", "materiali": "Disegni del corpo del modulo precedente; pennarello colorato", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Usando i disegni del modulo precedente, si chiede agli studenti di segnare con un colore le parti del corpo che ritengono più sensibili. Domande per la riflessione: la sensibilità è sempre legata a sensazioni piacevoli? Può cambiare o dipendere dalla situazione? È possibile che per la stessa parte del corpo ci piaccia un tipo di tocco ma non un altro? Messaggio chiave: ci sono fattori interpersonali e situazionali che influenzano se una sensazione è piacevole o no; alcune parti del corpo (es. genitali) sono altamente sensibili per la maggior parte delle persone.", "tag": "contatto fisico; emozioni e benessere; consenso"},
  {"nome": "Che cosa mi piace e che cosa non mi piace?", "modulo": "Kit scuole primarie – Modulo 3: Esplorare il corpo", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Prendere coscienza di ciò che sentiamo che ci piace o non ci piace e connettersi con i segnali del proprio corpo", "materiali": "Nessuno (attività di movimento)", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante disegna (reale o immaginaria) una linea per terra: da un lato 'Non mi piace', dall'altro 'Mi piace'. Descrive situazioni riguardanti il corpo (es. essere bagnati con acqua fredda, farsi solleticare i piedi, essere abbracciati quando si è arrabbiati) e gli studenti si posizionano su un lato o nell'altro. Opzionale: aggiungere gradualità (più vicino alla linea = sensazione più neutra). Alla fine si condividono le riflessioni emerse. Messaggio chiave: a volte è facile sapere se una sensazione è piacevole o spiacevole, ma non è sempre così e può variare a seconda della situazione e della persona.", "tag": "contatto fisico; consenso; emozioni e benessere"},
  {"nome": "Sì o no, non è così chiaro", "modulo": "Kit scuole primarie – Modulo 3: Esplorare il corpo", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Promuovere l'idea del consenso affermativo", "materiali": "Nessuno (attività di movimento) oppure pannello con sagoma umana e i tre colori del semaforo", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Usando la dinamica del modulo precedente (linea per terra), l'insegnante spiega che si possono distinguere tre tipi di sensazioni: sento che è un contatto che va bene (semaforo verde: continua); contatto confuso che mi fa dubitare (semaforo giallo: meglio rallentare o fermarsi); sento che è un contatto che non va bene o indesiderato (semaforo rosso: stop!). Poi si discute cosa fare in ciascuna situazione. Messaggi chiave: se senti un contatto indesiderato, non è colpa tua e chiedi aiuto; abbiamo sempre il diritto di dire no e possiamo cambiare idea. Fonte originale: guida SENTIR QUE SÍ, SENTIR QUE NO (Ajuntament de Barcelona).", "tag": "consenso; contatto fisico; comunicazione"},
  {"nome": "Come si sente un limite? L'abbraccio", "modulo": "Kit scuole primarie – Modulo 4: Comunicazione e consenso", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Capire come si sentono i limiti e favorire la capacità di capire le sensazioni del corpo in relazione ai propri limiti", "materiali": "Cartoncini per annotare sensazioni; ambiente con luce soffusa e musica dolce (per versione 2)", "partecipanti": "Intera classe; Versione 1: attività di visualizzazione; Versione 2: scansione del corpo guidata", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Attività di visualizzazione rilassata. Versione 1 (classi non inclini al rilassamento): l'insegnante propone scenari immaginari di abbracci (con persona amata che non vuole essere abbracciata; con persona non gradita che abbraccia; con persona amata reciprocamente) e chiede come si sente il corpo in ciascuna situazione, annotando le sensazioni su cartoncini. Versione 2 (classi più inclini): scansione del corpo guidata in silenzio (occhi chiusi o sdraiati), percorrendo piedi, gambe, schiena, braccia, collo fino alla pancia, chiedendo come si sente ogni parte. Da lì si immagina una persona cara che si avvicina e abbraccia, poi situazioni alternative (abbraccio non voluto, abbraccio in momento sbagliato). Alla fine si condividono le riflessioni sui segnali corporei e sulle domande che si potrebbero usare per chiedere il consenso.", "tag": "consenso; contatto fisico; emozioni e benessere"},
  {"nome": "Il semaforo del consenso", "modulo": "Kit scuole primarie – Modulo 4: Comunicazione e consenso", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Riflettere sul consenso nella presa di contatto con altre persone", "materiali": "Silhouette del corpo umano per ogni studente; pennarelli in 3 colori (verde, rosso, arancione); immagine di un semaforo stampata (opzionale)", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Si consegna a ogni studente una silhouette del corpo e 3 pennarelli. Codice colori: rosso = non va bene; arancione = non sono sicuro/a, forse; verde = va tutto bene. Gli studenti colorano le parti del corpo dove si sentono a proprio agio a essere toccati (verde), quelle che generano dubbi (arancione) e quelle più intime che non vogliono siano toccate (rosso). Domande di riflessione per le zone verdi: che tipo di tocco? La persona lo ha già provato? Questo tocco è comune tra amici? Messaggio chiave: tutte le zone possono cambiare colore a seconda della situazione e delle persone; nessuno può toccare i genitali o il seno se non lo decidiamo noi; se qualcuno, soprattutto un adulto, tocca queste aree, bisogna chiedere aiuto a un adulto di fiducia.", "tag": "consenso; contatto fisico; comunicazione"},
  {"nome": "L'immaginario della sessualità – Disegno libero", "modulo": "Kit scuole primarie – Modulo 5", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Riflettere sull'attuale immaginario della sessualità tra i giovani", "materiali": "Grandi fogli di carta o cartoncini; pennarelli", "partecipanti": "Intera classe; attività di libera associazione individuale poi discussione collettiva", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Usando grandi fogli di carta, si chiede agli studenti di disegnare cos'è per loro la sessualità (libera associazione). I disegni vengono poi discussi: cosa abbiamo disegnato? Dove abbiamo imparato ciò che abbiamo disegnato? Se le immagini richiamano un immaginario sessuale adulto, si chiede da dove vengono. Ci sono immagini che mostrano abbracci, affetto, carezze? Ci sono disegni che mettono a disagio? Nota per l'insegnante: se ragazzi e ragazze mostrano immagini significativamente diverse (ragazzi più sessualizzate, ragazze più emotive) segnalarlo e chiedere di riflettere sul perché. Messaggio chiave: la sessualità è un'esperienza molto ampia che include desiderio, affetto, carezze e non solo il sesso.", "tag": "sessualità; genere e stereotipi; emozioni e benessere"},
  {"nome": "L'immaginario della sessualità – Gioco di ruolo sul consenso", "modulo": "Kit scuole primarie – Modulo 5", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Approfondire la nozione di consenso, in particolare nell'area della sessualità", "materiali": "Nessuno (gioco di ruolo)", "partecipanti": "Intera classe; piccoli gruppi per il role-play", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Attraverso un gioco di ruolo, si propongono diverse situazioni di interazione sociale in cui una persona dice NO. Es.: un gruppo di persone a una festa spinge una persona a mangiare una fetta di torta. Si chiede al gruppo di rappresentare le situazioni e poi di riflettere: è stato facile dire di no? Che sensazione si prova quando non si può dire di no? Cosa cambieresti della situazione? L'insegnante può far ripetere il gioco con modifiche proposte. Risorsa video: Consenso: è semplice come il tè (YouTube). Messaggio chiave: abbiamo sempre il diritto di dire NO e possiamo farlo in qualsiasi momento; è più difficile sotto pressione; chi mette sotto pressione si rende responsabile di ignorare il tuo consenso.", "tag": "consenso; sessualità; comunicazione"},
  {"nome": "Stereotipi di genere", "modulo": "Kit scuole primarie – Modulo 6", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Presentare gli stereotipi di genere più comuni nella nostra società per affrontare le disuguaglianze che comportano nei moduli successivi", "materiali": "Foglio grande; penne; possibile uso del corpo degli studenti per tracciare sagome", "partecipanti": "Intera classe; lavoro in plenaria", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante disegna due sagome su un foglio grande (una ragazza, un ragazzo). Costruisce i personaggi insieme alla classe in base a diverse categorie: corpo, gusti, pensieri, sentimenti, che cosa le/gli piace. Una volta effettuata la divisione binaria si guida la riflessione: dove vediamo questi stereotipi (pubblicità, video, videogiochi)? Che cosa fanno i ragazzi/ragazze per dimostrare di essere maschi/femmine? Qual è il costo personale di vivere in questa scatola del genere? Cosa succede se qualcuno esce dalla scatola? Messaggio chiave: anche se vorremmo che questi stereotipi non esistessero, sono ancora presenti nella società; va bene non rispettarli.", "tag": "genere e stereotipi; violenza di genere; emozioni e benessere"},
  {"nome": "Che cos'è la violenza di genere? L'iceberg", "modulo": "Kit scuole primarie – Modulo 7", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Identificare la violenza di genere presente nel nostro ambiente, incluse le forme meno visibili", "materiali": "Lavagna o foglio grande per disegnare l'iceberg", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante disegna un iceberg e chiede agli studenti quali disuguaglianze di genere conoscono. In generale emergono: violenza nelle relazioni intime (psicologica, fisica, sessuale), violenza sessuale, disuguaglianze sul lavoro, distribuzione ineguale delle attività riproduttive. Usando la metafora dell'iceberg, si evidenziano le forme meno visibili di disuguaglianza nel contesto immediato degli studenti (es. uso ineguale della palla nei giochi, spazio occupato nel parco giochi, commenti sessualizzanti). Alla base ci sono gli stereotipi di genere discussi nel modulo precedente. Messaggio chiave: gli stereotipi di genere causano disuguaglianze che si riflettono in alcuni aspetti della sessualità insegnata dalla società.", "tag": "violenza di genere; genere e stereotipi; sessualità"},
  {"nome": "Abbiamo sentito parlare della violenza sessuale?", "modulo": "Kit scuole primarie – Modulo 8", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Comprendere la violenza sessuale nel quadro della violenza di genere in modo adeguato all'età", "materiali": "Lavagna (iceberg del modulo precedente)", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Continuazione dell'esercizio dell'iceberg precedente. Concentrandosi sulle violenze sessuali apparse sull'iceberg, l'insegnante pone domande: cosa sappiamo? Dove lo abbiamo sentito? C'è qualcosa che non capiamo? Pensi che ascoltare notizie su questi argomenti abbia lo stesso impatto su ragazzi e ragazze? Quali sono le differenze? Nota: questa è un'opportunità per rilevare come i discorsi sulla violenza sessuale si riferiscano spesso alla cultura del terrore sessuale. Messaggio chiave: la violenza sessuale riguarda la violazione dei limiti dell'altra persona e il mancato rispetto del consenso; non è mai responsabilità di chi la subisce.", "tag": "violenza di genere; sessualità; emozioni e benessere"},
  {"nome": "La pornificazione della cultura", "modulo": "Kit scuole primarie – Modulo 9", "durata": "30 minuti", "target": "Bambini e preadolescenti 10-12 anni; gestita da insegnanti", "obiettivo": "Identificare gli elementi di pornificazione nei riferimenti culturali e nei prodotti per bambini (TikTok, video musicali, personaggi videogiochi)", "materiali": "Nessuno specifico; eventuale proiezione di immagini o contenuti mediali adatti all'età", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole primarie (Progetto CONSENT n. 101049565)", "descrizione": "Prima dell'attività si avvia una conversazione sulle conoscenze pregresse degli studenti sulla pornografia. Si chiede poi quali sono i loro riferimenti culturali o i contenuti che guardano normalmente (TikTok, video musicali, personaggi dei videogiochi). In base alle risposte si guida la riflessione: pensi che quello che vediamo in queste immagini sia simile a quello che sappiamo o immaginiamo della pornografia? Come sono rappresentate le ragazze/i ragazzi? Pensi che rappresentino relazioni uguali o ineguali? Cosa si può spiegare sulla pornografia a quest'età: non è fatta per educare, è per adulti, alcune immagini mostrano violenza contro le donne, nelle relazioni reali tutte le persone devono sentirsi a proprio agio. Messaggio chiave: la pornografia è finzione e non è una rappresentazione accurata del sesso.", "tag": "pornografia; genere e stereotipi; violenza di genere"},
  {"nome": "Costruire uno spazio aperto sicuro", "modulo": "Kit scuole secondarie – Modulo 1", "durata": "30 minuti", "target": "Adolescenti 13-16 anni (3ª media – 2ª superiore); gestita da insegnanti", "obiettivo": "Creare il setting appropriato per avviare il programma e un ambiente condiviso in cui sia possibile parlare apertamente", "materiali": "Nessuno specifico (possibile tabella KWL)", "partecipanti": "Intera classe in cerchio", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Identico nella struttura al modulo 1 del kit primarie ma con contenuti adattati all'età (13-16 anni). L'insegnante spiega gli obiettivi del programma, anticipa le emozioni che potrebbero emergere (vergogna, piacere, curiosità, disagio), normalizza le risposte, chiede a chi parla di esperienze personali di rispettare la privacy, chiede agli studenti di scrivere un valore o atteggiamento che vorrebbero vedere nel gruppo. Messaggio chiave: nessuna vergogna e nessuna colpa.", "tag": "comunicazione; emozioni e benessere; sessualità"},
  {"nome": "Patriarcato: privilegi e oppressione", "modulo": "Kit scuole secondarie – Modulo 2: Introduzione dei contenuti generali", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Aumentare la consapevolezza sui privilegi di genere e sulle disuguaglianze strutturali", "materiali": "Strumento interattivo con anonimato (Mentimeter o Kahoot)", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante crea un questionario interattivo che garantisca l'anonimato. La prima domanda chiede il genere (maschio, femmina, non binario). Il questionario contiene un elenco di situazioni che mostrano diversi aspetti legati all'oppressione di genere; gli studenti rispondono Sì o No a seconda che le abbiano vissute direttamente. L'insegnante legge una frase alla volta e le percentuali vengono visualizzate sullo schermo mantenendo l'anonimato. Esempi di situazioni: sentirsi sessualizzati a causa dei vestiti; ricevere commenti sul corpo non richiesti; essere esclusi dallo sport; ricevere insulti a sfondo di genere o razzisti. Messaggio chiave: vivere da uomo o da donna porta a vivere situazioni diverse che rappresentano disuguaglianze; il genere non è l'unico asse che genera disuguaglianze sociali.", "tag": "genere e stereotipi; violenza di genere; comunicazione"},
  {"nome": "Stereotipi di genere e sessualizzazione delle donne", "modulo": "Kit scuole secondarie – Modulo 2: Introduzione dei contenuti generali", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Riflettere criticamente sugli stereotipi di genere e sull'oggettivazione e ipersessualizzazione di donne e ragazze nei media", "materiali": "Raccolta di immagini pubblicitarie e di videogiochi (Allegato 1); lavagna; tabella donne/uomini", "partecipanti": "Intera classe con lavoro individuale e plenaria", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Gli studenti analizzano campagne pubblicitarie e immagini di videogiochi. L'insegnante mostra la raccolta o la proietta sulla lavagna. Gli studenti identificano aspetti e caratteristiche (stereotipi, ruoli, comportamenti) rappresentati nelle immagini in base al genere usando una tabella Donne/Uomini con categorie: corpo, età, comportamento/ruolo, messaggio, a chi è rivolto, prodotto pubblicizzato. Domande di riflessione: cosa dice l'immagine sugli uomini? E sulle donne? Cosa non si vede? Come influisce su di noi? La sessualizzazione colpisce tutte le donne allo stesso modo? Messaggio chiave: la società e i media oggettivizzano e ipersessualizzano le donne e questo limita la libertà di espressione, azione e sentimento.", "tag": "genere e stereotipi; pornografia; sessualità"},
  {"nome": "Corpi normativi e il loro impatto", "modulo": "Kit scuole secondarie – Modulo 3: Esplorare e sentire il nostro corpo", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Prendere coscienza di come l'immaginario sociale influisce sull'esperienza del proprio corpo", "materiali": "Caratteristiche dei corpi dei modelli di ruolo scritte sulla lavagna o immagini/spezzoni di film", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante scrive alla lavagna le caratteristiche dei corpi che si vedono in film/serie/instagram/TikTok o mostra immagini di modelli di ruolo adattate agli studenti (es. Bella Hadid, Cristiano Ronaldo, Zendaya, Neymar). Si chiede: Le persone normali hanno queste caratteristiche? Ti sei mai sentito a disagio per non essere conforme a questi modelli? Quali conseguenze possono avere? Ti senti condizionato dai modelli che vedi? Messaggio chiave: vivere all'interno di questi canoni ha un costo personale e genera aspettative su noi stessi e sugli altri che impediscono di apprezzare la diversità dei corpi.", "tag": "genere e stereotipi; emozioni e benessere; sessualità"},
  {"nome": "Differenze nella sensibilità del corpo", "modulo": "Kit scuole secondarie – Modulo 3: Esplorare e sentire il nostro corpo", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Riflettere sulle diverse sensazioni e livelli di sensibilità corporea", "materiali": "Nessuno (dibattito aperto); opzionale: esercizio di scansione corporea", "partecipanti": "Intera classe con dibattito", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Il gruppo lavora sul fatto che corpi diversi hanno modi diversi di funzionare e diversi livelli di sensibilità. Si avvia un dibattito con domande aperte: pensi che la sensibilità sia la stessa in tutte le parti del corpo? Credi che tutti abbiano lo stesso livello di sensibilità? Pensi che l'intensità delle sensazioni possa cambiare? Cosa ti aiuterebbe a connetterti con il tuo corpo? Opzionale: esercizio di scansione corporea per spostare l'attenzione dai genitali alla totalità del corpo. Messaggio chiave: i corpi sono molto diversi e le sensazioni corporee possono cambiare nel tempo e in diverse situazioni; la consapevolezza del corpo è fondamentale per conoscere se stessi.", "tag": "contatto fisico; emozioni e benessere; sessualità"},
  {"nome": "Paure e vergogna nelle relazioni affettive e sessuali", "modulo": "Kit scuole secondarie – Modulo 4: Emozioni nelle interazioni sessuali e affettive", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Pensare a quali emozioni possono manifestarsi nelle relazioni affettive e sessuali ed esplorare strategie per affrontarle", "materiali": "Nessuno", "partecipanti": "Piccoli gruppi poi plenaria", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Gli studenti vengono divisi in gruppetti e ricevono domande per la riflessione. Rispondono in base alla propria immaginazione (non necessariamente esperienze personali). Domande: quali paure si possono manifestare? Da dove provengono? Come possiamo reagire alle nostre insicurezze? Come possiamo rispondere alle insicurezze degli altri? Messaggio chiave: le emozioni sono come una guida interna; non esistono emozioni positive o negative; alcune strategie per gestire emozioni difficili sono comunicarle all'altra persona o reindirizzare l'attenzione su altri stimoli.", "tag": "emozioni e benessere; sessualità; comunicazione"},
  {"nome": "Desiderio, eccitazione e piacere", "modulo": "Kit scuole secondarie – Modulo 4: Emozioni nelle interazioni sessuali e affettive", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Pensare ai limiti del desiderio, del piacere e della masturbazione da una prospettiva di genere", "materiali": "Dispositivo per riprodurre il video Oh My Goig – El plaer (link fornito)", "partecipanti": "Piccoli gruppi di circa 5 persone poi plenaria", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Visione di un video (Oh My Goig – El plaer, fino al minuto 6:10) e discussione in piccoli gruppi. Domande dalla meno alla più complessa a seconda dell'età: cosa succede ai personaggi del video? Pensi che ci siano differenze tra il desiderio maschile e femminile? Pensi che sia necessario prestare attenzione al desiderio dell'altra persona? Abbiamo bisogno di un'altra persona per provare piacere? Poi condivisione in plenaria. Messaggio chiave: per provare piacere bisogna sentirsi al sicuro, provare desiderio e curiosità; non è necessario stare con un'altra persona; comunicazione, rispetto e consenso sono necessari; la socializzazione di genere influenza il modo in cui le persone si relazionano al piacere.", "tag": "sessualità; emozioni e benessere; genere e stereotipi"},
  {"nome": "Comunicazione non verbale – La guida cieca", "modulo": "Kit scuole secondarie – Modulo 5: Comunicazione e consenso", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Essere consapevoli dei segnali non verbali reciproci e imparare a riconoscerli e a conoscerne l'importanza", "materiali": "Spazio libero per camminare", "partecipanti": "Coppie; tutta la classe in movimento", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Attività a coppie: una persona (guida) tiene la mano dell'altra (persona guidata) che ha gli occhi chiusi, per guidarla nello spazio in silenzio. La persona guidata può dare segnali non verbali per fermarsi o cambiare direzione. Dopo circa 5 minuti si scambiano i ruoli. Domande di riflessione: come ti sei sentito nel tuo ruolo? Hai notato che l'altra persona voleva fare qualcosa che non hai ascoltato? Hai percepito che l'altra persona ignorava i tuoi segnali? È facile percepire ciò che l'altra persona desidera? L'insegnante osserva anche da una prospettiva di genere. Messaggio chiave: la comunicazione non verbale è essenziale ma spesso implicita e vale sempre la pena chiedere esplicitamente; la sola comunicazione non verbale può portare a malintesi.", "tag": "comunicazione; contatto fisico; consenso"},
  {"nome": "Comunicazione sessuale", "modulo": "Kit scuole secondarie – Modulo 5: Comunicazione e consenso", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Riconoscere l'importanza del consenso per il pieno godimento della sessualità", "materiali": "Dispositivo per riprodurre il video PlayParty SidaStudi (link fornito)", "partecipanti": "Classe intera; eventualmente piccoli gruppi", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Visione del video PlayParty (SidaStudi) e discussione guidata. Domande: parlare durante il sesso è difficile o può essere sexy? Pensi che parlare o fare domande possa inibire o avere vantaggi? Ci sono cose più facili e più difficili da dire? Come possiamo dire che non ci piace qualcosa o che non vogliamo un rapporto sessuale? Come ti senti quando ti viene detto che all'altra persona non piace qualcosa? Messaggio chiave: esprimersi e chiedere in modo diretto aiuta a godere della sessualità; proporre alternative è possibile; è sempre possibile e diritto cambiare idea; arrabbiarsi al rifiuto è una forma di pressione.", "tag": "comunicazione; consenso; sessualità"},
  {"nome": "Esprimere e accettare i limiti", "modulo": "Kit scuole secondarie – Modulo 5: Comunicazione e consenso", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Sperimentare cosa significa stabilire/rispettare i limiti e riconoscere i propri bisogni e ciò che non ci piace", "materiali": "Spazio libero", "partecipanti": "Coppie che ruotano in due file", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Gli studenti si dispongono su due file uno di fronte all'altro formando coppie. Dopo essersi guardati negli occhi, una persona dice all'altra cosa vorrebbe fare (es. toccarti la schiena; sedermi vicino a te). Chi riceve può dire Sì o No ed eseguire o meno. Poi si invertono i ruoli. Si ruota cambiando coppie. Se rimane tempo, si fa un altro round. Nota: se si sente un commento a sfondo sessuale, interrompere e stabilire un limite con fermezza. Messaggio chiave: rifiutare una situazione o un'istruzione è un diritto.", "tag": "consenso; comunicazione; contatto fisico"},
  {"nome": "Che cos'è il consenso?", "modulo": "Kit scuole secondarie – Modulo 5: Comunicazione e consenso", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Capire che cos'è il consenso e quali caratteristiche deve avere; imparare a vivere interazioni salutari in cui è possibile stabilire un limite e che l'altra persona lo rispetti", "materiali": "Nessuno (discussione)", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Sulla base dell'attività precedente (esercizio in fila), si continua con domande di riflessione all'intero gruppo: che cos'è il consenso? Si può dire sì e poi cambiare idea? Come ci sentiamo quando l'altra persona dice no? Come ci sentiamo quando noi diciamo no? Guardando da una prospettiva di genere, è possibile che le ragazze trovino più difficile esprimere i propri limiti? Si fornisce poi la definizione di consenso (Convenzione di Istanbul) e si sottolinea: è sempre possibile cambiare idea; arrabbiarsi quando qualcuno dice no è una forma di pressione; la responsabilità della violenza sessualizzata è di chi trasgredisce i limiti, mai di chi li esprime.", "tag": "consenso; comunicazione; violenza di genere"},
  {"nome": "Violenza sessuale come violenza di genere", "modulo": "Kit scuole secondarie – Modulo 6", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Mostrare la piramide della violenza di genere per illustrare come atti presenti nella pornografia siano in altri contesti considerati violenza; identificare la violenza sessuale come forma di violenza di genere", "materiali": "Lavagna per disegnare iceberg/piramide", "partecipanti": "Intera classe; eventualmente piccoli gruppi", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante disegna un iceberg e chiede esempi di atti di violenza visti nella pornografia o di cui hanno sentito parlare. Posiziona gli atti sulla piramide/iceberg. Domande: come pensi che verrebbe percepito lo stesso comportamento in un ambiente pubblico? Come ti sentiresti? Perché la pornografia contiene tanta violenza e stupri? Cosa ne pensi della pornografia che mostra uomini che conquistano donne in modi diversi? Riflessione finale: la pornografia trasmette norme di mascolinità che promuovono la violenza sessuale; insegna ad aspettarsi la violenza sessuale; non insegna una sessualità basata sul consenso. Messaggio chiave: ciò che è considerato violenza sessuale nel mondo reale è la norma nella pornografia.", "tag": "violenza di genere; pornografia; genere e stereotipi"},
  {"nome": "Miti e fatti sulla pornografia", "modulo": "Kit scuole secondarie – Modulo 7: Affrontare la pornografia", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Decostruire i miti sulla pornografia e riflettere su come ci influenza", "materiali": "Strumento interattivo (Mentimeter o Kahoot)", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante crea un questionario interattivo con diversi miti sulla pornografia. Le possibili risposte sono: Mito, Verità, Ho dei dubbi. L'insegnante legge una domanda alla volta, gli studenti rispondono in anonimato e le risposte vengono visualizzate sullo schermo. Per ogni domanda l'insegnante fornisce le informazioni per decostruire il mito. Tabella miti/realtà fornita nel documento (es. la pornografia è educazione sessuale, la pornografia è solo fantasia, la pornografia non causa violenza).", "tag": "pornografia; violenza di genere; sessualità"},
  {"nome": "Analizzare la pornografia – Categorie, corpi, pratiche", "modulo": "Kit scuole secondarie – Modulo 7: Affrontare la pornografia", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Analizzare ciò che viene mostrato e ciò che non viene mostrato nella pornografia", "materiali": "Tabella da completare (fornita nel documento) con categorie: corpi, risposta sessuale, comunicazione, desiderio, categorie/etichette, pratiche sessuali – per uomini e donne", "partecipanti": "Intera classe", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "A partire dalla domanda 'Quali informazioni possiamo trovare in un video pornografico?', viene fornita una tabella da completare analizzando ciò che si vede nel porno per uomini e donne nelle categorie: corpi, risposta sessuale, comunicazione, espressione del desiderio, categorie/etichette, pratiche sessuali. Domande di riflessione: cosa non compare? Quali corpi o identità vengono resi invisibili? Come vengono rappresentati donne e uomini? Come ci influenza? Quali persone subiscono più violenza? Si vede il consenso? Messaggio chiave: la pornografia tradizionale riproduce e normalizza la violenza e gli stereotipi; mostra una risposta sessuale immediata senza lasciare spazio al consenso.", "tag": "pornografia; genere e stereotipi; violenza di genere"},
  {"nome": "Analizzare la pornografia – L'industria", "modulo": "Kit scuole secondarie – Modulo 7: Affrontare la pornografia", "durata": "30 minuti", "target": "Adolescenti 13-16 anni; gestita da insegnanti", "obiettivo": "Riflettere su chi vince e chi perde quando si tratta di produzione e diffusione di materiale pornografico", "materiali": "Fogli bianchi; lavagna", "partecipanti": "Coppie; plenaria", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "Identico nella struttura all'attività Vincitori e perdenti del manuale famiglie/insegnanti. Si divide la classe in coppie. Ogni coppia (10 min.) discute chi vince e chi perde nella pornografia e annota su un foglio diviso in due colonne. Condivisione in plenaria con brainstorming sulla lavagna (15 min.). Domande: perché pensi che siano vincitori/perdenti? Esistono altri collettivi colpiti non ancora nominati? Informazioni da trasmettere: la pornografia è un'industria multinazionale creata da uomini per uomini; sfrutta donne emarginate e vulnerabili; l'industria normalizza la violenza; le donne coinvolte subiscono gravi danni fisici e psicologici.", "tag": "pornografia; violenza di genere; genere e stereotipi"},
  {"nome": "Risorse e dove trovare supporto", "modulo": "Kit scuole secondarie – Modulo 8", "durata": "Non specificata (modulo informativo)", "target": "Adolescenti 13-16 anni che vivono o assistono a situazioni di violenza sessuale; gestita da insegnanti", "obiettivo": "Fornire ai giovani le risorse necessarie nel caso in cui si trovino in una situazione di violenza sessuale o assistano a violenze sessuali agite su altri", "materiali": "Elenco dei numeri di assistenza e servizi di supporto per vittime e sopravvissuti di violenza sessuale e di genere nella propria località", "partecipanti": "Intera classe o individuale", "fonte": "CONSENT – Kit per l'educazione affettiva nelle scuole secondarie (Progetto CONSENT n. 101049565)", "descrizione": "L'insegnante raccoglie in anticipo i contatti dei numeri di assistenza e dei servizi di supporto per le vittime e i sopravvissuti di violenza sessuale e di genere della propria area, in particolare quelli rivolti ai giovani. Fornisce agli studenti l'elenco con brevi spiegazioni. Se uno studente si rivolge all'insegnante per chiedere aiuto, è importante non forzarlo ma guidarlo seguendo il protocollo dell'istituto. Non incolparlo, monitorare attivamente. Messaggio chiave: non è mai responsabilità di chi la subisce ma di chi la agisce; non si tratta di sessualità ma di violenza.", "tag": "violenza di genere; emozioni e benessere; comunicazione"},
  {"nome": "Sessioni di rafforzamento delle capacità su clima e salute", "modulo": "GTA Toolkit – Phase 2, SEM Level 1: Gender-Transformative Change at the Individual Level", "durata": "Stage 1 (ToT): 3 giorni 6h/giorno; Stage 2 (Training CC): 3 giorni 6h/giorno; min. 2 settimane di preparazione tra Stage 1 e Stage 2", "target": "Donne adulte facilitatrici comunitarie (Climate Champions – CC); rappresentanti di CBO", "obiettivo": "Fornire alle donne Climate Champions (CC) le conoscenze e le competenze per collaborare con governi locali, scuole e comunità nell'identificare rischi climatici e di salute e contribuire a piani di resilienza locali", "materiali": "Manuali ToT e partecipanti su Climate Change, SRHR e Nutrizione; proiettore e laptop; flip charts colorati; pennarelli permanenti; forbici; colla; lavagna; scala per altezza bambini; nastro per circonferenza braccio", "partecipanti": "Stage 1: CBO representatives (facilitatori); Stage 2: gruppi di CC per distretto", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Due stadi. Stage 1 (Training of Trainers): il project staff adatta e traduce i manuali nelle lingue locali. Si facilita il ToT per i rappresentanti CBO concentrandosi su un tema diverso per giornata: Giorno 1 – cause e conseguenze del cambiamento climatico e panoramica della riduzione del rischio da disastri (DRR); Giorno 2 – effetti del cambiamento climatico su salute sessuale riproduttiva, pianificazione familiare, GBV e nutrizione; Giorno 3 – piani d'azione comunitari e preparazione ai disastri. Stage 2 (Training CC): i CBO cascadeano la formazione alle CC nei loro distretti ripetendo la struttura a 3 giorni tematici. Minimo 2 facilitatori per sessione; sessioni nelle lingue locali; metodi interattivi (icebreaker, energizer). Questa attività rafforza l'agency delle CC migliorando l'accesso alle informazioni e la fiducia nelle proprie capacità.", "tag": "cambiamento climatico; leadership femminile; comunicazione"},
  {"nome": "Potenziamento delle opportunità di sussistenza femminile", "modulo": "GTA Toolkit – Phase 2, SEM Level 1: Gender-Transformative Change at the Individual Level", "durata": "6 mesi per centri di sviluppo professionale; 2 giorni per cucina di giardino; variabile per altri mestieri", "target": "Donne adulte Climate Champions (CC) e altre donne della comunità", "obiettivo": "Dotare le CC di competenze per adottare pratiche di sussistenza resilienti al clima e generatrici di reddito per rafforzare l'autonomia economica e la sicurezza alimentare delle famiglie", "materiali": "Variabile per mestiere: macchine da cucire, tessuti, forbici, kit ricamo (sartoria); attrezzi da giardinaggio, semi, contenitori compost (cucina); canna di bambù, filo, forbici, strumenti per tessitura (artigianato)", "partecipanti": "Individuale o piccoli gruppi di CC con supporto CBO", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Il componente di sussistenza dota le CC di competenze in pratiche di produzione alimentare e generazione di reddito resilienti al clima. Passi: 1. Identificazione collaborativa dei mestieri resilienti al clima nel contesto locale. 2. Condivisione di informazioni sulle opportunità di lavoro nei workshop di dialogo GTA. 3. Le CC interessate contattano i loro CBO che le aiutano a identificare le competenze essenziali. 4. I CBO sviluppano piani di sussistenza completi. 5. Un comitato di revisione valuta i piani. 6. I CBO lavorano con le CC per implementare i piani. 7. I CBO monitorano e aggiustano. Esempi dal Pakistan: sartoria e ricamo (6 mesi), artigianato con bambù e canne (15 giorni), cucito boutique (2 mesi), estetista (1 mese); dal Bangladesh: agricoltura intelligente per la prevenzione delle inondazioni, allevamento pollame, cucito.", "tag": "leadership femminile; cambiamento climatico; genere e stereotipi"},
  {"nome": "Storytelling visivo – Le storie delle protagoniste", "modulo": "GTA Toolkit – Phase 2, SEM Level 1: Gender-Transformative Change at the Individual Level", "durata": "6 giorni totali (Ciclo 1: 3 giorni; Ciclo 2: 3 giorni) + 10 giorni di intervallo + 2-3 settimane di follow-up post-formazione", "target": "Donne adulte Climate Champions (CC)", "obiettivo": "Dotare le CC dell'uso dello storytelling visivo e dei principi della ricerca visiva partecipativa per condividere le proprie esperienze e prospettive sul cambiamento climatico e i suoi effetti su salute, sussistenza, nutrizione e GBV", "materiali": "Contratto con partner di visual storytelling locale; sala conferenze per distretto; manuale di formazione su fotografia e storytelling etico; tablet o smartphone forniti dal progetto; laptop; attrezzatura multimediale; flip charts; pennarelli permanenti; lavagna; colla", "partecipanti": "25 CC per distretto + 2 facilitatori esperti di visual storytelling per ciclo", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Training in 2 cicli. Preparazione: riunioni tra Pathfinder, CBO e partner di visual storytelling; sessioni online con ogni CBO per definire i criteri di selezione delle CC; visita esplorativa per valutare le competenze. Ciclo 1 (Giorni 1-3): Giorno 1 – fogli presenze e moduli consenso, norme del training; Giorni 2-3 – aspetti tecnici dello visual storytelling (basi della fotografia, sviluppo della storia attraverso le immagini, didascalie, concettualizzazione delle narrazioni); Giorno 3 – le CC praticano le competenze appena acquisite fotografando nella comunità. Intervallo di 10 giorni: le CC selezionano soggetti, catturano fotografie, documentano storie usando tablet forniti; i trainer offrono coaching su richiesta. Ciclo 2 (Giorni 4-6): workshop pratico culminante in mini-esposizioni a livello distrettuale il giorno finale.", "tag": "leadership femminile; comunicazione; cambiamento climatico"},
  {"nome": "Esercizio della scatola di genere", "modulo": "GTA Toolkit – Phase 2, SEM Level 2: Gender-Transformative Change at the Household Level", "durata": "2 ore", "target": "Adulti della comunità (uomini e donne); facilitatori: CC e alleati maschi", "obiettivo": "Incoraggiare la riflessione critica sulle norme di genere, le aspettative sociali e le dinamiche di potere attraverso discussioni di piccoli gruppi per genere", "materiali": "Grafici Act Like a Woman e Act Like a Man; flip charts e pennarelli; quaderni e penne", "partecipanti": "Gruppi per genere da 5-6 persone poi plenaria", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Passi: 1. I partecipanti vengono divisi in gruppi per genere da 5-6 persone che rappresentino identità diverse (livello educativo, stato civile, religione, professione). 2. Ogni gruppo femminile riceve un grafico Act Like a Woman; ogni gruppo maschile un grafico Act Like a Man. 3. 30 minuti per riempire i grafici con parole chiave o frasi associate al comportare come una donna/uomo secondo le norme sociali. 4. Almeno 2 membri per gruppo presentano i risultati. 5. Discussione plenaria che confronta i due grafici riflettendo su: motivazione delle scelte, connotazioni positive/negative, fattori che influenzano e rinforzano tali parole. Note facilitatore: quali sono le aspettative sui ruoli riproduttivi? E sulla gestione finanziaria? E sulla leadership femminile nel DRR?", "tag": "genere e stereotipi; violenza di genere; comunicazione"},
  {"nome": "Chi fa cosa? L'esercizio delle 24 ore", "modulo": "GTA Toolkit – Phase 2, SEM Level 2: Gender-Transformative Change at the Household Level", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne)", "obiettivo": "Comprendere l'impatto della divisione di genere del lavoro emersa dal Gender Box Exercise e rivelare la distribuzione ineguale del lavoro nel nucleo familiare", "materiali": "Flip chart; lavagna; pennarelli", "partecipanti": "Intera comunità presente divisa in donne e uomini per elenco separato poi plenaria", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Passi: 1. Si chiede alle donne/ragazze di descrivere i compiti che una donna svolge in una giornata tipica (dal risveglio), includendo sfere personali e pubbliche, usando una lente intersezionale. Tutti i compiti vengono registrati su un flip chart. 2. Si ripete con gli uomini/ragazzi su un flip chart separato. 3. Una volta completati entrambi i grafici, si apre la discussione: che somiglianze e differenze noti tra i due grafici? Quali sono i principali messaggi sulla divisione del lavoro? Cosa vorresti poter cambiare? Domande stimolo: coincidono le aspettative di genere emerse dal Gender Box con le divisioni del lavoro osservate nella vita reale?", "tag": "genere e stereotipi; leadership femminile; cambiamento climatico"},
  {"nome": "Campo di cotone o scuola?", "modulo": "GTA Toolkit – Phase 2, SEM Level 2: Gender-Transformative Change at the Household Level", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne)", "obiettivo": "Esaminare le contraddizioni tra norme di genere, aspettative sociali e pratiche reali mostrando come la mobilità delle donne e delle ragazze sia selettivamente controllata", "materiali": "Lavagna bianca; pennarelli", "partecipanti": "Intera comunità presente", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Passi: 1. Il facilitatore disegna sulla lavagna una ragazza in piedi su una strada tra un campo di cotone e una scuola e chiede: nella nostra società, dove è autorizzata ad andare questa ragazza – al campo di cotone o a scuola? 2. Si pone la domanda stimolo: perché le donne e le ragazze sono spesso escluse dalla scuola ma autorizzate a lavorare nei campi agricoli? 3. Si richiama il Gender Box Exercise: le norme di genere spesso stabiliscono che le donne restino a casa, eppure i grafici delle 24 ore hanno mostrato che le donne svolgono una varietà di attività fuori casa. 4. Si incoraggia una discussione più ampia: cosa succederebbe se le ragazze potessero andare a scuola? Se le donne potessero prendere lavoro in ufficio? Come cambierebbero i ruoli di uomini e donne nella famiglia?", "tag": "genere e stereotipi; leadership femminile; violenza di genere"},
  {"nome": "Impatto delle norme di genere sulla violenza di genere", "modulo": "GTA Toolkit – Phase 2, SEM Level 2: Gender-Transformative Change at the Household Level", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne); ATTENZIONE: argomento sensibile, possibili traumi latenti", "obiettivo": "Analizzare la relazione tra i risultati del Gender Box Exercise e la GBV; aiutare i partecipanti a identificare quali gruppi in società subiscono tipicamente violenza e come la GBV limita le opportunità di leadership delle donne", "materiali": "Cartellini; lavagna bianca e pennarelli", "partecipanti": "Intera comunità presente", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Passi: 1. Il facilitatore fa la transizione dall'Activity 3 chiedendo: cosa potrebbe succedere quando le donne e le ragazze frequentano la scuola, trovano lavoro o si battono per il cambiamento climatico? 2. Si facilita la discussione su come le comunità potrebbero reagire e come i partecipanti stessi potrebbero rispondere. 3. Si chiede: che impatto ha lo stigma sociale o le norme di genere sugli individui che assumono ruoli di leadership? 4. Si chiede: quale sarebbe l'impatto della GBV sulla partecipazione delle donne alla leadership e alle decisioni? 5. Il facilitatore annota tutte le risposte sulla lavagna e prosegue la discussione. 6. Si chiede: come possiamo sostenere le donne nel diventare Climate Champions considerando le aspettative sociali e la GBV? Nota: la GBV può riattivare traumi; i facilitatori devono rimanere attenti per tutto il tempo.", "tag": "violenza di genere; genere e stereotipi; leadership femminile"},
  {"nome": "Sessioni educative comunitarie a cascata", "modulo": "GTA Toolkit – Phase 2, SEM Level 3: Gender-Transformative Interventions at the Community Level", "durata": "90 minuti – 4 ore per sessione (variabile per location e disponibilità)", "target": "Comunità locali (donne, uomini, ragazze, ragazzi); facilitate da CC formate", "obiettivo": "Aumentare la consapevolezza della comunità sul cambiamento climatico e il suo impatto su SRHR, GBV, sussistenza e nutrizione, e rafforzare la visibilità del ruolo di leadership delle CC", "materiali": "Materiale IEC (Allegato 13); grandi libri per display; grafici; bandiere; stand; manuale Pathfinder su Climate Change, DRR, GBV, Nutrizione e SRHR (Allegato 14); pennarelli", "partecipanti": "Sessioni comunitarie aperte; gruppi separati per genere o misti", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Le CC organizzano sessioni comunitarie su 3 temi principali: 1. Comprensione del cambiamento climatico (cause, disastri indotti dal clima, tipi di eventi climatici; uso di grafici per supportare le spiegazioni e domande su disastri vissuti negli ultimi 2 anni). 2. Impatti del cambiamento climatico (effetti su vita comunitaria, sussistenza agricola e zootecnica, accesso alla salute e all'istruzione, impatti specifici su donne e ragazze). 3. Soluzioni potenziali (le CC invitano i membri della comunità a condividere idee per soluzioni a livello comunitario; si esplora come le comunità possono sostenere le donne in ruoli di leadership per le azioni climatiche). Per migliorare le sessioni future, le CC raccolgono feedback verbale con 5 domande guida. Spazio sicuro per donne: luogo fisicamente sicuro, lontano da case affollate; consenso informato prima di foto/video.", "tag": "cambiamento climatico; leadership femminile; comunicazione"},
  {"nome": "Arte e musica popolare per l'educazione climatica", "modulo": "GTA Toolkit – Phase 2, SEM Level 3: Gender-Transformative Interventions at the Community Level", "durata": "Stage 1: 2 giorni teatro + 5 giorni musica (6h/giorno); Stage 2: 1 ora teatro + 30 min. musica folk per evento", "target": "Comunità locali; CC (3 per distretto) e alleati maschi (3 per distretto) come performer; organizzazione artistica partner", "obiettivo": "Aumentare la consapevolezza della comunità sul cambiamento climatico e i suoi impatti sproporzionati su donne e ragazze, promuovere azioni di resilienza climatica guidate dalla comunità e migliorare la visibilità delle CC come leader e degli uomini come alleati", "materiali": "Stage 1: uffici partner CBO; costumi; script per teatro interattivo; composizioni musicali folk; quaderni e penne per facilitatori; Stage 2: script sviluppati; composizioni musicali folk; costumi; oggetti decorativi tradizionali; banner e stand per branding evento; bracciali per tracciare la partecipazione", "partecipanti": "6 CC + 3 alleati maschi per distretto (gruppi teatro e musica)", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Due stadi. Stage 1 – Skill building: si identifica e si onboarda un'organizzazione esperta in arte e musica per il cambiamento sociale. Si sviluppa uno script teatrale e canzoni nelle lingue locali in collaborazione con CBO e CC. Si selezionano 6 individui per distretto (3 CC e 3 alleati maschi) per formare gruppi teatro. Si conducono 2 giorni di training teatrale e 5 giorni di training musicale coprendo: dialogo, uso di costumi, espressioni corporee, modulazione della voce, tecniche di coinvolgimento del pubblico. Stage 2 – Performance: si selezionano luoghi appropriati in ogni comunità. Si programmano eventi serali quando più persone della comunità sono disponibili. Si invitano i membri almeno un giorno prima. Si conduce lo spettacolo di teatro interattivo e l'evento di musica folk focalizzati sul cambiamento climatico e i suoi impatti specifici su donne e ragazze. Dopo la performance si invitano i membri a condividere riflessioni sul messaggio.", "tag": "cambiamento climatico; leadership femminile; comunicazione"},
  {"nome": "Soluzioni basate sulla natura guidate da donne", "modulo": "GTA Toolkit – Phase 2, SEM Level 3: Gender-Transformative Interventions at the Community Level", "durata": "Variabile per intervento", "target": "Comunità locali; CC come leader; CBO come supporto; autorità distrettuali", "obiettivo": "Introdurre e promuovere soluzioni basate sulla natura per la resilienza climatica (piantagione di mangrovie, pesca sostenibile, agricoltura climate-smart); rafforzare le competenze delle CC nel trasferire conoscenze teoriche in azioni pratiche; coinvolgere attivamente le comunità in piani d'azione climatici collettivi; modificare le norme di genere elevando le donne come leader della resilienza climatica", "materiali": "Semi di mangrovie; semi di colture agricole; guida per la piantagione e la coltivazione delle colture scelte", "partecipanti": "CC + membri della comunità + funzionari distrettuali", "fonte": "GTAToolkit – Toolkit for Applying a Gender-Transformative Approach to Women-Led Climate Resilience (Pathfinder International / Takeda, ottobre 2025)", "descrizione": "Passi: 1. I piani d'azione di resilienza climatica sviluppati durante SEM Level 1 vengono identificati e si selezionano quelli focalizzati su soluzioni basate sulla natura. 2. Le CC si interfacciano con i coordinatori di distretto del progetto e con esperti CBO di piantagione di mangrovie per rivedere e affinare le proposte. 3. Il CBO include l'intervento nell'agenda delle riunioni di coordinamento distrettuale per ottenere il sostegno delle autorità locali. 4. Le CC presentano la proposta alla direzione distrettuale durante le riunioni multisettoriali per integrare l'intervento nella pianificazione formale del distretto. 5. Con l'approvazione delle autorità distrettuali, le CC tornano nelle comunità per pianificare. 6. Le CC programmano le giornate di piantagione una volta ottenuti i semi dai CBO. 7. Il CBO organizza la logistica (veicoli, barche per zone costiere). 8. Le CC guidano la campagna di piantagione con i membri della comunità e i funzionari. 9. La comunità monitora i germogli per proteggerli da parassiti e bestiame.", "tag": "cambiamento climatico; leadership femminile; genere e stereotipi"},
  {"nome": "Esercizio della scatola di genere", "modulo": "GTADialogueWorkshopGuide – Day 1", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne, ragazze e ragazzi); facilitatori: CC formate e alleati maschi", "obiettivo": "Incoraggiare la riflessione critica sulle norme di genere, le aspettative sociali e le dinamiche di potere; porre le basi per un'ulteriore analisi delle cause profonde della disuguaglianza di genere e delle restrizioni alla partecipazione delle donne alla leadership e al processo decisionale", "materiali": "Grafici Act Like a Woman e Act Like a Man; flip charts e pennarelli; quaderni e penne", "partecipanti": "Gruppi per genere da 5-6 persone poi plenaria", "fonte": "GTADialogueWorkshopGuide – Manual for Applying Gender-Transformative Approach for Dialogue Workshop (Pathfinder International – WLCR Program)", "descrizione": "Stessa struttura del Gender Box Exercise del GTA Toolkit. I partecipanti vengono divisi in gruppi per genere da 5-6 persone con identità diverse. Ogni gruppo femminile riceve il grafico Act Like a Woman; ogni gruppo maschile il grafico Act Like a Man. 30 minuti per riempire i grafici con parole chiave associate al comportarsi come una donna/uomo secondo le norme sociali. Presentazione in plenaria di almeno 2 membri per gruppo. Discussione facilitata: motivazione delle scelte, connotazioni positive/negative, fattori che influenzano questi modelli. Domande stimolo: cosa insegniamo ai nostri figli sull'agire come donna/uomo? Come sono le aspettative sui ruoli riproduttivi e sulla gestione finanziaria? Quali aspettative sociali ci sono per la leadership femminile nel DRR? Questo esercizio è il fondamento per le attività successive (Activiy 2-8).", "tag": "genere e stereotipi; violenza di genere; comunicazione"},
  {"nome": "Impatto delle norme di genere sulla divisione del lavoro", "modulo": "GTADialogueWorkshopGuide – Day 1", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne)", "obiettivo": "Comprendere l'impatto della divisione di genere del lavoro; rivelare la distribuzione ineguale del lavoro nel nucleo familiare", "materiali": "Flip chart; lavagna; pennarelli", "partecipanti": "Intera comunità presente divisa in donne e uomini", "fonte": "GTADialogueWorkshopGuide – Manual for Applying Gender-Transformative Approach for Dialogue Workshop (Pathfinder International – WLCR Program)", "descrizione": "Identico all'Activity 2 del GTA Toolkit (24-Hours-a-Day Exercise). Si chiede alle donne di descrivere i compiti di una giornata tipica (dal risveglio, sfere personali e pubbliche) registrando tutto su un flip chart. Si ripete con gli uomini su un flip chart separato. Si confrontano i due grafici in plenaria con domande stimolo: che somiglianze e differenze? Quali i messaggi principali sulla divisione del lavoro? Cosa vorresti cambiare?", "tag": "genere e stereotipi; leadership femminile; cambiamento climatico"},
  {"nome": "Campo di cotone o scuola? Accesso alle risorse", "modulo": "GTADialogueWorkshopGuide – Day 1", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne)", "obiettivo": "Esaminare le contraddizioni tra norme di genere e pratiche reali mostrando come la mobilità delle donne sia selettivamente controllata", "materiali": "Lavagna bianca; pennarelli", "partecipanti": "Intera comunità presente", "fonte": "GTADialogueWorkshopGuide – Manual for Applying Gender-Transformative Approach for Dialogue Workshop (Pathfinder International – WLCR Program)", "descrizione": "Identico all'Activity 3 del GTA Toolkit. Il facilitatore disegna una ragazza tra un campo di cotone e una scuola e chiede dove è autorizzata ad andare nella loro società. Si discute perché le ragazze sono spesso escluse dalla scuola ma autorizzate al lavoro agricolo. Si richiama il Gender Box e i grafici delle 24 ore per mostrare la contraddizione. Domande di approfondimento: cosa succederebbe se le ragazze potessero andare a scuola? Se le donne potessero prendere lavoro negli uffici governativi?", "tag": "genere e stereotipi; leadership femminile; violenza di genere"},
  {"nome": "Impatto delle norme di genere sulla violenza di genere", "modulo": "GTADialogueWorkshopGuide – Day 2", "durata": "1 ora", "target": "Adulti della comunità (uomini e donne); ATTENZIONE: argomento sensibile", "obiettivo": "Analizzare la relazione tra norme di genere e GBV; identificare quali gruppi subiscono tipicamente violenza e come la GBV limita le opportunità di leadership delle donne", "materiali": "Cartellini; lavagna bianca e pennarelli", "partecipanti": "Intera comunità presente", "fonte": "GTADialogueWorkshopGuide – Manual for Applying Gender-Transformative Approach for Dialogue Workshop (Pathfinder International – WLCR Program)", "descrizione": "Identico all'Activity 4 del GTA Toolkit. Il facilitatore fa la transizione dall'Activity 3 chiedendo cosa potrebbe succedere quando le donne frequentano la scuola o si battono per il cambiamento climatico. Si discute come le comunità reagirebbero e come i partecipanti stessi potrebbero rispondere. Si approfondisce l'impatto dello stigma sociale sugli individui con ruoli di leadership e l'impatto della GBV sulla partecipazione delle donne alla leadership e alle decisioni. Il facilitatore chiede come si può sostenere le donne nel diventare Climate Champions. Nota: possibili traumi latenti; i facilitatori devono restare attenti durante tutta la sessione.", "tag": "violenza di genere; genere e stereotipi; leadership femminile"},
  {"nome": "Analisi dell'albero dei problemi", "modulo": "GTADialogueWorkshopGuide – Day 2", "durata": "Non specificata", "target": "Adulti della comunità (uomini e donne)", "obiettivo": "Analizzare le cause profonde e gli effetti dei problemi di genere legat", "materiali": "", "partecipanti": "", "fonte": "", "descrizione": "", "tag": "genere e stereotipi; violenza di genere; cambiamento climatico"},
  {"nome": "Tre cose in comune", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Rompere il ghiaccio e scoprire cosa si condivide, accogliendo anche il disaccordo", "materiali": "Nessuno", "partecipanti": "Coppie che si scambiano, poi gruppo intero in cerchio", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "I partecipanti si muovono nella stanza e formano coppie: ogni coppia trova tre cose in comune, andando oltre le più ovvie (gelato, pasta, birra). Si possono cambiare 2 o 3 coppie. Poi, seduti in cerchio, il gruppo cerca tre cose che tutti hanno in comune. A ogni proposta («qui amiamo tutti il calcio») il facilitatore chiede se vale davvero per ciascuno, incoraggiando a dissentire e accogliendo le differenze. Se partecipa, il facilitatore deve essere pronto a prendere posizione su affermazioni problematiche («qui odiamo tutti il carcere, le donne, i gay…»); oppure può restare fuori, limitandosi a chiedere se l'affermazione è condivisa da tutti e a lavorare sulle emozioni che la sostengono.", "tag": "conoscenza del gruppo; comunicazione"},
  {"nome": "Sono l’unico qui che…", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Far emergere ciò che rende unica ogni persona del gruppo", "materiali": "Nessuno", "partecipanti": "Gruppo intero in cerchio", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In cerchio, ogni persona dice qualcosa che la rende unica nel gruppo, ad esempio «Sono l'unico qui che nuota nell'oceano tutto l'anno». Ogni volta il facilitatore chiede se qualcun altro si riconosce nella frase, per verificare che nessun altro lo faccia.", "tag": "conoscenza del gruppo; comunicazione"},
  {"nome": "Presentarsi in coppia e presentare l’altro al gruppo", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Allenare l’ascolto e riflettere su quanto facilmente si dimentica ciò che gli altri dicono di sé", "materiali": "Nessuno", "partecipanti": "Coppie, poi gruppo intero in cerchio", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In coppia, ciascuno si presenta all'altro per un minuto. Tornati in cerchio, ognuno presenta al gruppo il proprio compagno. Qualcuno avrà dimenticato ciò che gli è stato detto, a volte anche il nome, o non avrà ascoltato: non va rimproverato, può dire ciò che ricorda o improvvisare, senza pressione né giudizio. Ne può nascere una discussione: perché dimentichiamo facilmente i nomi e le informazioni sugli altri? Quali informazioni sono rimaste più impresse? Quando hai scoperto che dovevi riferire al gruppo e non ricordavi quasi nulla, cosa hai provato, pensato, deciso? Il gioco invita ad ascoltarsi meglio in futuro.", "tag": "comunicazione; conoscenza del gruppo"},
  {"nome": "Due verità e una bugia", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Conoscersi in modo leggero e allenarsi a parlare di sé davanti al gruppo", "materiali": "Nessuno", "partecipanti": "Gruppo intero in cerchio", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Ogni partecipante dice tre cose su di sé: due vere e una falsa. Il gruppo deve indovinare quale è falsa. Chi ha parlato può anche scegliere di non rivelare la risposta.", "tag": "conoscenza del gruppo; comunicazione"},
  {"nome": "Presentarsi come un altro venuto a sostituirti", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Guardarsi da fuori e far emergere, con l’ironia, cosa la persona pensa del programma e delle proprie relazioni", "materiali": "Nessuno", "partecipanti": "Gruppo intero in cerchio o coppie", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Ogni partecipante si presenta come se fosse un'altra persona venuta a sostituirlo: Joe finge di essere Jack, che è lì perché Joe non è potuto venire. Il gruppo fa domande a Jack su Joe: perché Joe non è venuto? È la vera ragione? È il tipo che sparisce facilmente? Le domande permettono al facilitatore di raccogliere informazioni che altrimenti non emergerebbero (cosa pensa Joe del programma, perché si sente obbligato a partecipare) e costringono Joe a uscire da sé e a vedersi dall'esterno. Il facilitatore può incoraggiare Jack a scherzare su Joe per arrivare alle sue relazioni personali e intime. Fonte originale: Rino Cerritelli (Humour Therapy, Milano).", "tag": "empatia e punti di vista; conoscenza del gruppo"},
  {"nome": "Mi piace / non mi piace", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Conoscersi muovendosi nello spazio e far emergere, anche in forma anonima, perché si partecipa o non si vorrebbe partecipare al programma", "materiali": "Nessuno", "partecipanti": "Coppie che si scambiano, poi discussione in cerchio", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "I partecipanti si muovono nella stanza e, ogni volta che incontrano qualcuno, gli dicono una cosa che amano e una che non sopportano (ad esempio musica e calcio) senza dire quale delle due: l'altro deve indovinare. Ognuno incontra almeno tre persone. La stessa dinamica funziona con «un motivo per cui voglio essere in questo programma e uno per cui non voglio». Funziona meglio se fatto rapidamente. Alla fine si raccolgono le cose interessanti emerse, anche in forma anonima: chi riferisce non deve dire chi ha detto cosa.", "tag": "conoscenza del gruppo; comunicazione"},
  {"nome": "Il tuo posto nella stanza", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Creare fiducia e un patto informale di gruppo a partire da dove ciascuno si sente a suo agio", "materiali": "Sedie", "partecipanti": "Gruppo intero, ognuno per sé", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Si chiede ai partecipanti di andare nel punto della stanza in cui si sentono più a loro agio: qualcuno andrà il più lontano possibile dal centro, altri proprio al centro, qualcuno girerà la sedia verso l'esterno o si metterà vicino alla porta. Ogni posizione viene esplorata con domande, per raccogliere informazioni e costruire un patto di gruppo informale: chi sta vicino alla porta vuole sentire di avere una via d'uscita da ogni attività? Il facilitatore riformula con il partecipante lasciando spazio a ciò che è positivo: riconoscere con rispetto paure e distanze aiuta a creare un clima sicuro e rispettoso.", "tag": "conoscenza del gruppo; emozioni e benessere"},
  {"nome": "La mappa sul pavimento", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Esplorare origini, luoghi e situazioni di rischio dei partecipanti, e da lì le radici della loro idea di maschilità", "materiali": "Nessuno", "partecipanti": "Gruppo intero, ognuno per sé", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Il pavimento diventa una grande mappa, con nord, sud, est e ovest: la mappa della città se si lavora su temi locali, quella del mondo per parlare di dove si vorrebbe o non si vorrebbe vivere. I partecipanti si posizionano con la maggiore precisione possibile, verificando con i vicini. Le domande possono essere: da dove vengono i tuoi nonni? Dove vorresti vivere? Dove hai passato il periodo più bello della tua vita? Dove ti sei messo nei guai? Dove ti senti in pericolo? Dove hai fatto più male? Dove sei tu il pericolo? Dove ti arrabbi più facilmente? Dove ti senti competente e apprezzato? Spostandosi verso i luoghi dei nonni emerge spesso che quasi tutti hanno una storia di migrazione in famiglia. Per lavorare sulle maschilità si può chiedere di trasformarsi nella statua del nonno o di un uomo tipico del luogo d'origine, e poi discuterne. Non insistere quando una risposta è vaga e non spingere a rivelare dettagli che si vogliono tenere per sé. Fonti originali: Jale Karabekir (Istanbul); Geese Theatre Handbook (2002).", "tag": "genere e stereotipi; conoscenza del gruppo; violenza di genere"},
  {"nome": "Luoghi pericolosi", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Partire dai pericoli concreti della stanza per arrivare a riconoscere quando si è un pericolo per qualcuno", "materiali": "Nessuno", "partecipanti": "Gruppo intero, ognuno per sé", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "I partecipanti, in piedi o seduti, individuano nella stanza luoghi o oggetti potenzialmente pericolosi: un tavolo laterale se tutti si muovono, il gradino vicino alla porta su cui inciampare. Ogni volta si immagina come evitare il pericolo durante gli incontri. L'esercizio apre a domande più personali: qual è un luogo pericoloso nella tua vita? C'è una persona che eviti, e perché? Come eviti le situazioni pericolose? Quando sei tu il pericolo, e per chi? Funziona bene prima o dopo «La mappa sul pavimento». Fonte originale: Geese Theatre Handbook (2002).", "tag": "responsabilità; violenza di genere; emozioni e benessere"},
  {"nome": "Lo stesso percorso", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Far sperimentare che si può sempre migliorare, rendendo il cambiamento desiderabile e realistico", "materiali": "Nessuno", "partecipanti": "Gruppo intero, ognuno per sé", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "I partecipanti si distribuiscono nella stanza e memorizzano il punto in cui si trovano. Devono compiere il più velocemente possibile quattro azioni, in qualsiasi ordine, e tornare al loro posto: toccare due pareti diverse, stringere la mano a tre persone, girare attorno a una sedia, toccare il pavimento. Si cronometra fino al ritorno dell'ultimo (la prima volta circa 30 secondi). Poi si chiede: com'è andata? Quali difficoltà? Cosa si può migliorare? Quali strategie sono personali e quali vanno decise insieme? Si ripete finché c'è entusiasmo, 5-6 volte con i più giovani e 3 con i più anziani (correre non è sempre la soluzione più veloce). Domanda finale: se le difficoltà del gioco fossero i momenti della tua vita in cui sei arrivato o arriveresti a usare violenza, cosa potresti fare per cambiare il percorso abituale? Fonte originale: Geese Theatre Handbook (2002).", "tag": "responsabilità; conoscenza del gruppo"},
  {"nome": "Sogni e fantasie", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Favorire una partecipazione positiva con domande leggere da proporre nel corso del programma", "materiali": "Nessuno", "partecipanti": "Gruppo intero, ognuno per sé", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "I partecipanti rispondono brevemente a domande che si possono proporre una ogni settimana o ogni due incontri: cosa faresti se fossi il presidente del paese? Se vincessi alla lotteria? Se mancassero 5 minuti alla fine del mondo? Dove andresti se potessi partire adesso? Se perdessi tutti i ricordi tranne uno, quale terresti? Se potessi incontrare una persona a tua scelta, chi sarebbe e cosa le diresti? Fonte originale: James Thompson, Drama Workshops for Anger Management and Offending Behavior (1999).", "tag": "emozioni e benessere; conoscenza del gruppo; comunicazione"},
  {"nome": "Se qualcuno mi tampona la macchina, io…", "modulo": "WWP Giochi e strumenti teatrali – 1. Attività semplici per iniziare", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Imparare a distinguere pensieri, emozioni, sensazioni fisiche e comportamenti", "materiali": "Lavagna o fogli per annotare le risposte", "partecipanti": "Gruppo intero, ognuno per sé", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Ogni partecipante completa la frase «Se qualcuno mi tampona la macchina, io…». Il facilitatore annota le risposte e il gruppo le colloca in quattro categorie: pensieri, emozioni, sensazioni fisiche, comportamenti. «Mi spavento molto» va tra le emozioni; dove vanno «prendo a pugni il guidatore» o «urlo contro il guidatore»? L'esercizio allena a distinguere le quattro categorie e prepara ad altri esercizi sulle emozioni.", "tag": "emozioni e benessere; comunicazione"},
  {"nome": "Ali, Ali, Ali", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5-15 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Esplorare le emozioni e lo stress di stare sotto i riflettori, e come uscirne", "materiali": "Nessuno", "partecipanti": "Gruppo intero in cerchio; da 5 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Tutti in cerchio, in piedi o seduti; una persona sta al centro. Per uscire deve dire tre volte, molto velocemente, il nome di un altro («Ali Ali Ali»). Se Ali riesce a dire il proprio nome prima che il suo sia ripetuto tre volte, si salva; altrimenti va lui al centro e tocca a lui sorprendere qualcuno. Chi sta al centro può sentirsi sotto stress e non trovare nemmeno un nome: va riconosciuto, e il gruppo può riflettere su quali trucchi funzionano. Aiuta se anche il facilitatore gioca e accetta lo stress di stare al centro. Domande durante il gioco: come ti senti al centro, sotto i riflettori? Perché ci si blocca? Dopo il gioco: quando ti succede nella vita? Come gestisci il sentirti bloccato? Come hai trovato la strategia giusta per uscire? Risultati attesi: sperimentare uno stress accettabile, capire le proprie emozioni sotto pressione, gestire sentimenti forti. Fonte originale: gioco egiziano, descritto in Chris Johnston, Drama games for those who like to say no (2010).", "tag": "emozioni e benessere; conoscenza del gruppo"},
  {"nome": "Saluta più persone che puoi: uomini e donne, potenti e impotenti", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Non specificata: saluti di 10 secondi, discussione anche lunga", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Scoprire con il corpo che il genere è un costrutto sociale e che comportarsi da «vero uomo» può essere faticoso, noioso e dannoso", "materiali": "Nessuno", "partecipanti": "Gruppo intero in movimento; da 6 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Passo 1: in 10 secondi, mentre il facilitatore conta, i partecipanti salutano più persone possibile; si possono aggiungere varianti (in modo molto formale, con i gomiti, con i piedi). Passo 2, il più importante: salutare più persone possibile come si salutano tipicamente gli uomini tra loro. Passo 3, da gestire con cura: salutare come si salutano tipicamente le donne, per non più di 10 secondi; chi si sente a disagio può non partecipare senza sentirsi escluso. Passi 4 e 5, le domande: com'erano i saluti maschili? Erano tutti uguali? Cambiano con l'età, il luogo, la cultura? Sono naturali o si imparano, e dove? E quelli femminili, dove e perché si imparano? Variante: salutare sentendosi potenti e poi impotenti, prima dei saluti di genere, per esplorare il potere; oppure salutare provando un'emozione (rabbia, tristezza, vergogna, orgoglio, paura). Risultati attesi: aprire una discussione su potere e genere, distinguere ciò che è dato alla nascita da ciò che si impara, collegarlo ad altri comportamenti appresi come la violenza o il fare i duri. Fonte originale: il gruppo drag king Eyes Wild Drag.", "tag": "genere e stereotipi; potere e controllo"},
  {"nome": "Hola Barcelona", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5 minuti - 1 ora", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Esplorare il genere e altri costrutti sociali scambiandosi parole in forma anonima", "materiali": "Nessuno", "partecipanti": "Gruppo intero in movimento; da 6 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1 (al massimo 2 minuti): dico il mio nome a qualcuno, lui mi dice il suo e ce li scambiamo; vado da un altro, dico il nuovo nome e ne ricevo un altro ancora, finché magari riottengo il mio. Tutti si muovono insieme. Discussione: perché ci disturba ed è difficile cambiare nome? Spesso emerge la perdita d'identità e l'idea che il cervello sia «programmato» su un nome: anche il genere è una programmazione. Parte 2 (al massimo 2 minuti): invece dei nomi ci si scambiano parole, la prima che viene in mente sentendo «uomo», non la più intelligente né la più corretta; nessuno alla fine ricorderà chi ha detto cosa. Domande: quali parole sono uscite? «Barba», «muscoli», «cravatta» valgono solo per gli uomini? Cosa succede a scuola a una ragazza molto forte? Quali parole sono costrutti sociali e quali biologia? Che conseguenze ha associare gli uomini alla forza e le donne alla debolezza? Si può ripetere su amore, potere, ideale romantico, sessualità. Conviene mostrare il gioco invece di spiegarlo a parole. Fonte originale: Féminisme Enjeux (Parigi); parte sul genere di Parteciparte (Roma).", "tag": "genere e stereotipi; comunicazione; sessualità"},
  {"nome": "Costruire insieme", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5-20 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Lavorare sulla cooperazione e prendere coscienza delle proprie tendenze al controllo", "materiali": "Un foglio di carta per coppia", "partecipanti": "Coppie; da 2 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In coppia, con un foglio, i partecipanti devono costruire un aeroplano di carta usando una sola mano ciascuno: l'altra resta sempre dietro la schiena. Il facilitatore non interviene, se non per ricordare questa regola. Quando tutti sono pronti si lanciano gli aerei e si valorizzano tutti i voli, curvi, corti o lunghi: sono i tanti modi in cui una relazione può volare. Chi tende a imporsi si blocca, perché il gioco richiede la piena collaborazione dell'altro. Domande: com'è andata? C'era spazio per le proposte di entrambi? Come avete negoziato e deciso ogni mossa? Eri più passivo o più aggressivo? Succede anche in altre situazioni della tua vita? Dove avresti potuto fare diversamente? Vuoi riprovare, magari con un altro compagno? Varianti: allacciare una scarpa, mettere e togliere una felpa, guidare a voce un compagno bendato, disegnare insieme senza parlare. Si può rifare a casa con la partner o la famiglia, anche filmandosi per rivedersi. Fonte originale: Geese Theatre Handbook (2002).", "tag": "potere e controllo; comunicazione"},
  {"nome": "99-55", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5-60 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Definire comportamenti accettabili e inaccettabili, imparare a riconoscere le proprie responsabilità e a riparare una relazione", "materiali": "Nessuno", "partecipanti": "Coppie; da 4 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In coppia, uno conta all'indietro da 99 a 55 mentre l'altro cerca di disturbarlo per fargli sbagliare o fermarsi; poi ci si scambia. Si può semplificare (da 30 a 1) o far contare nella propria lingua. All'inizio c'è caos e ilarità. Poi si raccoglie cosa si è fatto per disturbare: contare numeri sbagliati, fare domande personali, parlare del corpo dell'altro, toccare, fare il solletico, prendere in giro. Domande: nella vita reale cosa è accettabile e cosa no (ad esempio commentare di continuo l'aspetto di una collega invece delle sue capacità)? Puoi decidere tu per l'altro cosa è accettabile? Fai alcune di queste cose nella tua vita? Se ti accorgi di aver disturbato qualcuno, come ricostruisci una relazione sana? E dall'altra parte: come hai mantenuto la concentrazione? Se 55 fosse una vita senza violenza, quali ostacoli incontreresti? Le strategie usate ti aiuterebbero a controllare il tuo comportamento? Si possono poi provare in coppia brevi scene su come riconoscere di aver mancato di rispetto. Varianti: contare da 100 sottraendo 7; «fammi ridere», senza toccarsi né parlare. Fonte originale: Geese Theatre Handbook (2002); la parte sulla responsabilità è dell'autore del manuale.", "tag": "responsabilità; consenso; violenza di genere"},
  {"nome": "Santi e peccatori", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "10-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Cambiare prospettiva, costruire empatia e lavorare sulla violenza verbale", "materiali": "Nessuno", "partecipanti": "Piccoli gruppi di massimo 5 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Si formano due o più gruppi di massimo 5 persone: i santi e i peccatori. A ogni gruppo si fa la stessa richiesta: «Potresti abbassare il volume della musica?». In 1-2 minuti i santi concordano la risposta più gentile possibile, i peccatori la peggiore. Dopo ogni risposta i gruppi si scambiano i ruoli. La risposta sgarbata offre una rapida sociologia collettiva di insulti e parolacce, che spesso esprimono sessismo, razzismo, ageismo, omofobia e altre discriminazioni: cosa significano, da dove vengono, che effetto hanno su chi li riceve e su chi li usa? E cosa rende così gentile la risposta dei santi? Variante: un continuum con i santi da un lato della stanza e i peccatori dall'altro. Dove sei adesso nella tua vita? Dove eri prima? Dove vorresti essere? Cosa te lo impedisce? Come può aiutarti il programma? Perché alcuni pensano che essere più aggressivi porti più rispetto? Fonte originale: Geese Theatre Handbook (2002).", "tag": "comunicazione; empatia e punti di vista; violenza di genere"},
  {"nome": "La giusta distanza", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Prendere coscienza che l’altro può avere bisogni diversi dai propri e accettare le sue decisioni", "materiali": "Spazio libero", "partecipanti": "Coppie su due file; da 4 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "I partecipanti si dispongono su due file, A e B, una di fronte all'altra, a 4-5 metri. Al segnale chi sta in A cammina verso la persona di fronte finché questa lo ferma con un gesto della mano: è B a decidere quanto vicino può arrivare, e A deve accettarlo (e può fermarsi prima, se lo preferisce). Ci si guarda negli occhi per circa 30 secondi, poi A torna indietro e si invertono i ruoli. Bisogna fermare l'altro prima che diventi invadente, a una distanza in cui ci si sente a proprio agio a guardarsi negli occhi. Domande: come ti sei sentito quando l'altro ti ha fermato? E quando hai fermato tu? Vi siete fermati alla stessa distanza? Cosa provi scoprendo che altri hanno bisogno di più distanza di te? Ci sono situazioni in cui non ti accorgi di andare troppo vicino? Controlli sempre di essere alla distanza giusta con la partner o gli amici? Se ti chiedono più distanza, vuol dire che la relazione non è buona? Fonte originale: Birgit Fritz (Vienna) e Stefania Girelli (Milano).", "tag": "consenso; contatto fisico; empatia e punti di vista"},
  {"nome": "Il conflitto dal punto di vista della tazza", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Rendere visibili lo scaricare la colpa, la negazione e la minimizzazione", "materiali": "Nessuno", "partecipanti": "Gruppo intero in cerchio oppure coppie; da 2 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Il facilitatore mostra l'esercizio raccontando un conflitto recente con un figlio o una partner. Mentre una persona racconta, il gruppo si allontana quando il racconto è centrato su di sé, scarica la colpa, minimizza o giustifica, e si avvicina quando si mette nei panni dell'altro o si assume la responsabilità. Ad esempio: «mio figlio voleva raccontarmi tante cose mentre lavoravo al computer, mi sono arrabbiato perché deve imparare che non sono sempre disponibile» (il gruppo si allontana); «capisco però che voleva condividere quello che gli era successo a scuola e che gli bastavano cinque minuti» (il gruppo si avvicina). Per fare prima si lavora in coppia, poi si prova con tutto il gruppo su una o due storie. Domande: cosa hai provato vedendo gli altri allontanarsi o avvicinarsi? Cosa succederebbe se in un conflitto ti concentrassi di più sul punto di vista dell'altro? Cosa puoi cambiare da ora? Varianti: dito verso il basso per la minimizzazione, mani alzate per la responsabilità, spalle girate per la negazione; i segnali possono diventare un'abitudine del gruppo per tutto il programma. Fonte originale: Kris Dekraemer, Evan Hastings, Augusto Boal (1992).", "tag": "responsabilità; empatia e punti di vista"},
  {"nome": "Chiunque…", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "5-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Fare una mappa degli stereotipi e dei pregiudizi presenti nel gruppo, senza giudicare", "materiali": "Sedie, una in meno dei partecipanti", "partecipanti": "Gruppo intero in cerchio; da 6 a 25 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1: tutti seduti in cerchio, una persona al centro senza sedia. Dice qualcosa di sé che altri potrebbero condividere: «Chiunque ama il gelato». Chi si riconosce deve alzarsi e cambiare sedia (non quella accanto né la propria); chi è al centro cerca di sedersi e chi resta in piedi va al centro. Parte 2: quando il gioco funziona, le frasi iniziano con «Chiunque pensa che gli uomini…» o «Chiunque pensa che le donne…» («…che gli uomini sono più coraggiosi delle donne», «…che le donne non sanno guidare»). Chi è d'accordo, anche in parte, cambia sedia. All'inizio non si analizza nulla e non si giudica. Discussione: sulle frasi che hanno suscitato più reazioni ci si dispone vicino o lontano da chi le ha dette, secondo quanto si è d'accordo, e il facilitatore fa dialogare le posizioni evitando le generalizzazioni («in quale situazione è stato vero per te?»). Si può fare anche su violenza, giustizia, pornografia. Non è uno sport di contatto: meglio restare al centro che finire in ospedale. Fonte originale: Muriel Naessens (Féminisme Enjeux); Christina Zoniou (Grecia).", "tag": "genere e stereotipi; conoscenza del gruppo"},
  {"nome": "Continuum, opposizioni, difendi l’opposto", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Almeno 10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Far emergere le posizioni, le differenze tra pari e i cambiamenti di atteggiamento nel corso del programma", "materiali": "Nessuno", "partecipanti": "Gruppo intero; anche con una sola persona", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Un lato della stanza significa «completamente d'accordo», l'altro «completamente in disaccordo». Il facilitatore propone frasi e i partecipanti si posizionano: «le donne hanno il diritto di fare ciò che vogliono», poi «gli uomini hanno il diritto di fare ciò che vogliono», poi «fare sesso è un diritto» o «le donne possono fare ciò che vogliono purché non danneggino la reputazione della famiglia». Anche i partecipanti possono proporre frasi. Se la discussione si fa aggressiva aiutano l'ascolto attivo tra posizioni opposte e «difendi l'opposto»: due persone in disaccordo si scambiano di posto e devono sostenere in modo credibile la posizione dell'altro, scambiandosi più volte. Si può iniziare in coppia su temi neutri (bici contro auto, lavoro da casa contro ufficio), con il facilitatore che batte le mani per invertire i ruoli. A chi dice che la sua posizione non cambierà mai si chiede cosa pensava a 10, 20 o 30 anni. L'esercizio si può riprendere in qualsiasi momento per misurare i cambiamenti. Fonte originale: Geese Theatre Handbook (2002); Rus Funk sulla pornografia (2018); Mouhamadou Diol (Senegal) per «difendi l'opposto».", "tag": "genere e stereotipi; empatia e punti di vista; comunicazione"},
  {"nome": "Ascolto attivo: fatti ed emozioni", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "15-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Sviluppare l’ascolto attivo e la capacità di riconoscere e nominare le emozioni altrui", "materiali": "Nessuno", "partecipanti": "Gruppi di tre; da 3 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In gruppi di tre: la persona 1 racconta un conflitto non troppo grave; la 2 ascolta i fatti (dove, quando, chi); la 3 ascolta le emozioni. Finito il racconto, la 2 fa domande di verifica e riferisce ciò che ha capito; quando la 1 conferma «hai capito tutto», la 3 riferisce le emozioni che ha colto e verifica che la 1 si riconosca. Si ruota tre volte, in modo che tutti provino i tre ruoli. Chi racconta può scoprire emozioni di cui non era consapevole: va dato spazio. Domande: com'è stato essere ascoltato così intensamente? Come ti sei sentito ricevendo il riscontro sui fatti, e quello sulle emozioni? E se non ti riconoscevi in un'emozione? Dove nella tua vita ti servirebbe più spesso questo esercizio? Fonte originale: First Alternative Dispute Resolution Kit (2018).", "tag": "emozioni e benessere; comunicazione; empatia e punti di vista"},
  {"nome": "Ipnosi colombiana", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "12-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Esplorare con il corpo l’empatia, l’abuso di potere e la perdita di controllo", "materiali": "Spazio libero", "partecipanti": "Coppie; meglio gruppi di 4-6 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1, empatia e collaborazione (2-5 minuti): in coppia, A guida B con il palmo della mano, e il viso di B deve restare a circa 20 cm dal palmo. Senza parlare, A cerca di capire cosa può chiedere a B senza pretendere l'impossibile. Parte 2, dominio (2-5 minuti): A abusa gradualmente del suo potere portando B in posizioni sempre più difficili. Parte 3, emancipazione (2-5 minuti), senza interrompere il gioco: B può ribellarsi, prima in modo nascosto e sottile poi sempre più esplicito, finché A perde il potere e B non reagisce più ai suoi movimenti. Poi si invertono i ruoli. Domande: come ti sei sentito a guidare e a essere guidato? L'altro teneva conto delle tue reazioni? Come ti sei sentito con il pieno potere sull'altro, e senza nessun potere? Come hai reagito capendo che stavi perdendo il controllo? Come succede nella tua vita? Varianti: catene di persone che si guidano; versione indiana (tutti si fermano in una statua e il gruppo immagina la storia violenta dietro un'immagine); versione italiana (tutti immobili improvvisano a voce, insieme, la storia della propria statua per un minuto). Fonte originale: Augusto Boal (1992); NAJE (Parigi); Jana Sanskriti (India); Parteciparte (Roma).", "tag": "potere e controllo; empatia e punti di vista"},
  {"nome": "Angeli e diavoli in movimento 1", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Almeno 20 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Riflettere su consenso, pressione, molestie e morale giocando con il bene e il male", "materiali": "Nessuno", "partecipanti": "Gruppi di tre; da 3 a 12 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In gruppi di tre: la persona 1 ha due consiglieri, un angelo e un diavolo. L'angelo la convince a fare cose buone e concrete (dire qualcosa di gentile a un altro partecipante, fare un gesto amichevole, offrire qualcosa); il diavolo la spinge a fare il contrario (una battuta cattiva su qualcuno, dire qualcosa di sgarbato, togliere gli occhiali a qualcuno). Angelo e diavolo possono anche litigare tra loro, tra caos e risate. Ognuno resta in ogni ruolo 2-4 minuti; di solito ci si scalda dal secondo giro. Domande: chi ha avuto più influenza su di te? Perché hai accettato certi compiti? Hai fatto qualcosa che non volevi davvero fare o che normalmente non faresti? Cosa ti ha convinto? Come potresti resistere alla tentazione o alla pressione? Più facile dopo «99-55». Fonte originale: Emanuele Avallone (clown).", "tag": "consenso; potere e controllo"},
  {"nome": "Angeli e diavoli in movimento 2", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Almeno 5 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Ampliare il repertorio di ruoli e allenarsi a passare gradualmente da un ruolo all’altro", "materiali": "Spazio libero", "partecipanti": "Coppie; da 4 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In coppia, ad almeno 4 metri di distanza: uno è l'angelo (suoni dolci, gesti amorevoli), l'altro il diavolo (suoni strani e sarcastici, cerca di spaventare l'angelo). Si muovono insieme avanti e indietro lungo una linea: più si allontanano più diventano il loro personaggio, più si avvicinano più il personaggio si fa leggero, fino al punto neutro al centro dove passano dall'altra parte e si scambiano il ruolo, il più gradualmente possibile. Domande: perché a molti piace di più fare il diavolo? Cosa hai provato e pensato in ciascun ruolo? Com'è stato passare gradualmente da un ruolo all'altro? Variante: se il gruppo ha già giocato con maschile e femminile, angeli e diavoli diventano uomini e donne, molto accentuati da lontano e sempre meno vicino alla linea. Meglio dopo «99-55» o «Tragedia greca». Fonte originale: Si les Sardines avaient des ailes; Caravane théâtre; Parteciparte per la variante di genere.", "tag": "genere e stereotipi; empatia e punti di vista"},
  {"nome": "Tragedia greca e violenza psicologica", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Almeno 15 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori; ATTENZIONE: possono tornare alla mente i propri oppressori del passato", "obiettivo": "Vedere all’opera la violenza psicologica, verbale ed emotiva in un contesto protetto, e riconoscere la propria", "materiali": "Nessuno", "partecipanti": "Gruppo intero, poi coppie; da 4-6 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1: il gruppo impara tutto insieme un pezzo di tragedia mostrato dal facilitatore: «O dèi (mani in alto), la città di Troia (mani avanti a indicarla) è distrutta (mani che scendono)». Parte 2: in coppia, uno è l'attore e l'altro il direttore artistico, che gli chiede di ripetere il pezzo ancora e ancora senza essere mai soddisfatto. Dura 2 minuti, poi ci si scambia. Parte 3: in gruppo si elenca cosa fa un direttore artistico «cattivo» (cosa dice, come lo dice, il linguaggio del corpo), senza dire chi ha fatto cosa: ne esce una definizione completa di violenza psicologica, verbale ed emotiva. Chi altro si comporta così? (capi, insegnanti, genitori…). Poi si ribalta l'elenco in positivo. Parte 4: nelle coppie si riflette sulle strategie usate da direttori e su dove si è imparato quel comportamento. Parte 5: si condivide in gruppo. Parte 6: in coppia, come si riconosce di aver agito in modo dannoso e come si ricostruisce una relazione sana? Chiedere perdono, spiegare a lungo, o chiedere all'altro come si è sentito? Cercare anche le forme più sottili, quelle che si esercitano con un sorriso gentile. Variante meno teatrale: uno disegna e l'altro lo sminuisce di continuo per 2 minuti. Fonte originale: Emmanuel Gallot Lavallée (clown); Parteciparte (Roma).", "tag": "violenza di genere; potere e controllo; responsabilità"},
  {"nome": "Un, due, tre, nonna", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "15-30 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Passare dalla competizione al lavoro collettivo e prepararsi al teatro immagine", "materiali": "Una bottiglia o un altro oggetto", "partecipanti": "Gruppo intero; da 6 a 20 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1: è il gioco tradizionale simile a «un, due, tre, stella». I partecipanti partono da un lato della stanza; la «nonna» conta 1-2-3 di spalle e a occhi chiusi, poi si gira: chi viene visto muoversi torna al punto di partenza. Chi tocca piano la spalla della nonna le toglie il potere e prende il suo posto. Parte 2: ora deve arrivare alla nonna un oggetto, una bottiglia, passandolo di mano in mano (mai lanciato). Quando si gira, la nonna può accusare qualcuno, che deve mostrare le mani: se ha la bottiglia, si ricomincia tutti da capo. Il gruppo deve accordarsi su una strategia. Parte 3: prima di contare, la nonna annuncia un'emozione o un personaggio («rabbia, 1-2-3!») e rimanda indietro chi non lo sta rappresentando. Domande: come ti senti quando vieni rimandato indietro e lo trovi ingiusto? E la nonna, quando il gruppo si avvicina e sta per perdere il potere? Chi contestava gli abusi della nonna li ripete quando diventa nonna? Cosa ha portato il gruppo al successo? Varianti: versione greca senza nessuno al comando; versione bendata sull'arbitrarietà del potere. Fonte originale: gioco tradizionale; Geese Theatre Handbook (2002); Parteciparte; Christina Zoniou.", "tag": "potere e controllo; emozioni e benessere; conoscenza del gruppo"},
  {"nome": "Non sei nella mia testa?", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Almeno 10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Far capire che nessuno può leggere nel pensiero e allenare una comunicazione chiara", "materiali": "Fogli e penne", "partecipanti": "Coppie; da 2 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "In coppia, A fa un disegno molto semplice e poi spiega a B come rifarlo, senza mai dire cosa rappresenta: non «disegna una testa con i capelli lunghi» ma «disegna un cerchio; dalla parte alta partono linee che scendono curve lungo il cerchio…». Alla fine si confrontano i disegni. B scopre quanto è difficile capire cosa c'è nella testa di un altro, A quanto è difficile comunicare con chiarezza. Le differenze vanno lette in positivo: i due disegni insieme sono un'opera d'arte a cui la coppia dà un titolo. Domande: come ti sei sentito quando l'altro non capiva? E quando il tuo disegno era diverso? Come ti sentirai tra 10 minuti, un giorno, un anno? Variante: con e senza la possibilità per B di fare domande. Quale funziona meglio? Ci sono situazioni nella tua vita in cui non vuoi o non puoi ricevere riscontri? Non richiede di recitare né di muoversi, quindi va bene per i primi incontri.", "tag": "comunicazione; empatia e punti di vista"},
  {"nome": "Attraversare la stanza sui fogli", "modulo": "WWP Giochi e strumenti teatrali – 2. Giochi di approfondimento", "durata": "Almeno 10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Lavorare in gruppo su strategia, frustrazione e abuso di potere di chi prende il comando", "materiali": "Due o tre fogli di giornale, oppure tre sedie", "partecipanti": "Gruppo intero o due squadre; da 6-8 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Il gruppo parte da un lato della stanza e deve arrivare tutto dall'altra parte senza mai toccare il pavimento, camminando solo su pochi fogli di giornale (2 fogli per 6-10 persone, 3 per 11 o più), che non bastano a fare un ponte: serve una strategia. Con almeno 14 persone si fanno due squadre. Spesso qualcuno prende il comando in modo poco produttivo, ad esempio prende tutti i fogli, attraversa e prova a rilanciarli, che finiscono a metà stanza fuori portata. Il facilitatore commenta senza colpevolizzare («c'è sempre una prima strategia che non funziona, grazie per averla mostrata: il gruppo vuole decidere insieme un'altra strategia?») e aiuta chi ha preso il potere a fare un passo indietro e a esserne lui stesso critico. Domande: come si è organizzato il gruppo? Cosa si può fare quando succedono cose negative? Come vi riorganizzereste per la strategia perfetta? Varianti: con le sedie; teatro forum sul momento in cui qualcuno prende il potere nel gruppo. Fonte originale: Julian Boal (Brasile).", "tag": "potere e controllo; conoscenza del gruppo; comunicazione"},
  {"nome": "Introduzione al teatro immagine", "modulo": "WWP Giochi e strumenti teatrali – 3. Teatro immagine e sculture", "durata": "Almeno 5 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Introdurre il teatro immagine: usare il corpo per creare statue che mostrano emozioni, conflitti e disuguaglianze", "materiali": "Nessuno", "partecipanti": "Gruppo intero, coppie o piccoli gruppi; da 2 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Nel teatro immagine i partecipanti usano il corpo per creare una statua immobile, individuale o di gruppo, che poi viene commentata dagli altri e analizzata con il facilitatore. Si comincia velocemente e con un tempo limite: «in due avete 5 secondi per fare un orologio, in tre 10 secondi per una barca, in quattro una famiglia». Oppure si cammina e ci si ferma allo stop, poi si aggiunge un'emozione da rappresentare (rabbia, paura, orgoglio, disgusto); si può organizzare un «museo della rabbia». Serve un rituale per fermarsi e ripartire (contare 1-2-3, battere le mani); le statue non parlano e non si commentano da sole. Domande di base: cosa prova questo personaggio? Quali sono i suoi pensieri segreti? Cosa vuole, cosa dice? Variante: tre immagini di una storia vera (il momento prima dell'offesa, la violenza, le conseguenze) che diventano poi una breve scena in movimento, con scambi di ruolo per mettersi nei panni dell'altro. Fonte originale: Augusto Boal (1992-1995); Geese Theatre Handbook (2002).", "tag": "emozioni e benessere; empatia e punti di vista"},
  {"nome": "Il cerchio dei punti di vista", "modulo": "WWP Giochi e strumenti teatrali – 3. Teatro immagine e sculture", "durata": "Almeno 5 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Rendere evidente che ogni cosa ha più di un punto di vista, compreso quello della vittima", "materiali": "Una sedia", "partecipanti": "Gruppo intero in cerchio; da 4 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Un volontario siede su una sedia al centro del cerchio e non fa nulla. Il facilitatore chiede a vari partecipanti quanti occhi, orecchie e mani vedono: chi è dietro vede due orecchie, due mani e nessun occhio; chi è di lato un occhio e un orecchio; chi è davanti due occhi. Poi si cambia posto e si ripete. Le conclusioni sembrano ovvie, quindi bisogna essere pronti a portare il discorso più in là: chi ha ragione? Qualcuno ha torto? Succede anche in altre situazioni? Quando gli altri punti di vista ti mettono in difficoltà? Cosa penseresti di chi sostiene che il volontario ha un solo occhio ed è la verità assoluta, e si arrabbia se lo contraddici? Saresti capace e disposto a guardare le cose dal punto di vista della tua vittima? Come ti vedono le persone intorno a te? Si può proseguire con un continuum o con scene di teatro forum. Fonte originale: Geese Theatre Handbook (2002).", "tag": "empatia e punti di vista; responsabilità"},
  {"nome": "Esercizio a due A/B", "modulo": "WWP Giochi e strumenti teatrali – 3. Teatro immagine e sculture", "durata": "Almeno 10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Rendere chiaro cosa significa violenza di genere e quanto il potere sia sbilanciato tra uomini e donne", "materiali": "Una sedia", "partecipanti": "Gruppo intero che osserva due volontari; da 5 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Un volontario, o una co-facilitatrice, siede davanti al gruppo guardando il pavimento; un altro, un uomo, sta in piedi dietro di lei, di lato, immobile, e la guarda. Il gruppo immagina una storia problematica tra i due e dà loro un nome: emergono presto storie di violenza, tradimento, molestie, stalking, quasi sempre con lui che opprime lei. Se ci sono solo uomini, si raccolgono prima storie di conflitto tra due uomini, poi si chiede al volontario seduto se accetta di essere interpretato come una donna, senza esagerare la femminilità. Inversione: ora è lei in piedi dietro e lui seduto. Le stesse storie funzionano ancora? Spesso il gruppo ride perché non riesce a immaginarlo spaventato o perseguitato da lei: va esplorato. Senza minimizzare la violenza femminile quando emerge, l'esercizio porta a riconoscere che nella maggior parte dei casi sono gli uomini a essere più violenti verso le donne. Da una delle storie si può passare al role play o al teatro forum. Variante: l'uomo dietro si avvicina in tre momenti, per lavorare anche sullo spazio personale. Fonte originale: Geese Theatre Handbook (2002).", "tag": "violenza di genere; genere e stereotipi; potere e controllo"},
  {"nome": "L’immagine della parola: uomo e donna, al tuo meglio e al tuo peggio", "modulo": "WWP Giochi e strumenti teatrali – 3. Teatro immagine e sculture", "durata": "5 minuti - 2 ore", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Lavorare con il corpo su concetti difficili: maschilità e femminilità, e gli stati intermedi tra il proprio meglio e il proprio peggio", "materiali": "Nessuno", "partecipanti": "Gruppo intero, individuale o in coppia", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1: in cerchio, rivolti verso l'esterno; il facilitatore dice una parola (religione, paura…) e in tre secondi ognuno si gira verso l'interno facendone un'immagine con il corpo. Parti 2 e 3: si fa un'immagine di «uomini», poi di «donne», osservando anche quelle degli altri. Parte 4: dall'immagine «uomini», al battito di mani ci si trasforma al rallentatore in «donne», esplorando ogni muscolo e ogni cambiamento, e poi di nuovo in uomini, almeno due volte: per molti uomini è stata un'esperienza che ha cambiato la vita. Parte 5: si formano «famiglie» di immagini simili (ad esempio una maschilità muscolosa) e si commentano partendo dai dettagli fisici (il mento in alto) per arrivare alle interpretazioni (orgoglio), riconoscendo la pluralità delle maschilità. A ogni immagine si può chiedere un suono, un movimento, una parola. Domande: chi sono gli uomini che hanno ispirato la tua immagine? Come ti sei sentito a rappresentare la femminilità? Variante: «tu quando ti senti al tuo meglio» e «tu al tuo peggio», cercando le immagini intermedie e facendole dialogare, per aiutare a evitare gli stati d'animo estremi. Fonte originale: Augusto Boal, L'arcobaleno del desiderio (1995); Muriel Naessens; Umberta Telfener.", "tag": "genere e stereotipi; emozioni e benessere"},
  {"nome": "Angeli e diavoli in movimento 3", "modulo": "WWP Giochi e strumenti teatrali – 3. Teatro immagine e sculture", "durata": "Almeno 15 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori; ATTENZIONE: si lavora su storie personali di rabbia", "obiettivo": "Mettere in discussione i pensieri di rabbia e la tendenza a minimizzare, negare, scaricare la colpa e mettersi al centro", "materiali": "Nessuno", "partecipanti": "Gruppo intero che osserva quattro persone in scena; da 3 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Parte 1A: una persona (il protagonista) racconta una storia di rabbia e, con un altro partecipante (l'antagonista), crea un'immagine immobile del momento più conflittuale; poi i due improvvisano il conflitto a parole per 1-2 minuti, senza muoversi. Dietro il protagonista arrivano un angelo, che propone pensieri pacifici, e dopo 15-30 secondi un diavolo, che alimenta i pensieri di rabbia e spinge a comportamenti più aggressivi. Poi il protagonista affronta il diavolo faccia a faccia e cerca di smontarne gli argomenti; se non ne ha più, altri partecipanti possono sostituirlo e mostrare come lo affronterebbero. Parte 1B, facoltativa: i ruoli si rovesciano, l'angelo sostiene con complicità i pensieri di rabbia («poverino, ti provoca di nuovo») e il diavolo li smonta con ironia. Parte 2: il protagonista affronta da solo il personaggio che ha dato voce ai suoi pensieri più pericolosi. Varianti: sullo scaricare la colpa («è tutta colpa sua»), sul narcisismo, sul vittimismo, sui pensieri svalutanti verso se stessi. Fonte originale: James Thompson (1999); Parteciparte; Evan Hastings.", "tag": "responsabilità; emozioni e benessere; violenza di genere"},
  {"nome": "La finta stretta di mano", "modulo": "WWP Giochi e strumenti teatrali – 4. Role play e teatro forum", "durata": "Almeno 10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Introdurre il teatro forum: provare più strategie per rispondere a una provocazione senza violenza", "materiali": "Nessuno", "partecipanti": "Gruppo intero che osserva e interviene; da 4 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Il facilitatore annuncia una piccola scena e chiede un volontario, che deve solo reagire. Il facilitatore, ora attore, tende la mano come per stringergliela e, quando il volontario si avvicina, la ritira in modo sgarbato e gli volta le spalle. Poi torna facilitatore e chiede al pubblico: cosa è successo? Perché il personaggio si è comportato così, quale potere lo fa sentire in diritto? Ci sono situazioni simili nella vostra vita? Cosa si può fare? Chi vuole provare? I partecipanti entrano in scena e provano alternative. Le reazioni violente si possono mostrare solo al rallentatore e senza fare male, mostrandone le conseguenze: cosa succederebbe dopo? Ci sono alternative? Ogni proposta va valorizzata («cosa ci piace di questo intervento?»). Dopo almeno quattro alternative si conclude: anche in situazioni rapide e oppressive le possibilità sono molte. È come avere il tasto per riavvolgere: nella vita gli errori possono essere definitivi, nel teatro forum il cambiamento si prova quante volte serve. Varianti: qualcuno ti passa davanti in fila alla posta; un ufficio pubblico non ti risponde perché sei straniero o giovane; compagni che ridono di chi è rimasto con la mano tesa. Fonte originale: Julian Boal (Brasile).", "tag": "emozioni e benessere; comunicazione; responsabilità"},
  {"nome": "La sorella della tua partner sta con un uomo violento", "modulo": "WWP Giochi e strumenti teatrali – 4. Role play e teatro forum", "durata": "Almeno 10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori; ATTENZIONE: non lasciare che la violenza venga minimizzata o resa simpatica", "obiettivo": "Far vedere dall’esterno cosa significa la violenza di genere e quanto è difficile e rischioso intervenire per aiutare una donna", "materiali": "Un libro come oggetto di scena", "partecipanti": "Gruppo intero che osserva e interviene; da 4 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Due partecipanti interpretano una coppia a cui il gruppo dà un nome, ad esempio Mary e Peter: Peter è aggressivo e la svaluta continuamente. Un terzo, Nasser, è chi cerca di smontare questa oppressione: la sua compagna è malata e gli chiede di andare dalla sorella, Mary, a prendere un libro. Nasser parla con Mary e intuisce che qualcosa non va; Peter entra, crea tensione e lo prende in giro per essere «sottomesso» alla compagna; poi esce, lasciando a Nasser un'ultima occasione per parlare con Mary. In questi tre momenti i partecipanti possono sostituire Nasser e provare le loro idee. Il gruppo costruisce insieme pensieri ed emozioni dei personaggi. Nel teatro forum Mary non va sostituita: farlo suggerirebbe che le basterebbe fare la cosa giusta per liberarsi. Molti interventi possono metterla in pericolo e va detto chiaramente; spesso ascoltarla e farle domande fa già la differenza. Se emerge «lei dovrebbe…», chiedere: perché Mary è ancora con Peter? È stupida? Non lavoriamo su perché lei resta, ma su perché lui è violento e su cosa possiamo fare. Se chi interpreta Peter lo rende simpatico o giustifica la violenza, lo si fa sostituire. Domande: cosa hai in comune con Peter? Che consiglio gli daresti? Peter potrebbe cambiare? Variante: è la propria sorella a essere intrappolata. Fonte originale: Chris Johnston (2010); uno spettacolo di teatro forum creato con case rifugio.", "tag": "violenza di genere; empatia e punti di vista; responsabilità"},
  {"nome": "L’hanno vista abbracciare un altro uomo", "modulo": "WWP Giochi e strumenti teatrali – 4. Role play e teatro forum", "durata": "15 minuti - 2 ore", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori; ATTENZIONE: scene che possono accendere molto i partecipanti", "obiettivo": "Lavorare sulla gelosia e sulla rabbia che ne nasce, smontando l’idea che la partner sia una proprietà", "materiali": "Nessuno", "partecipanti": "Gruppo intero che osserva e interviene; da 5 persone", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Si chiede ai partecipanti cosa proverebbero, penserebbero e farebbero se sapessero che la loro partner è stata vista abbracciare un altro uomo. Prima di iniziare si decide quale ipotesi esplorare: un equivoco (era il cugino, il fratello) oppure una relazione. Due volontari interpretano la scena. Opzione 1: il partecipante deve informarsi parlando con la partner. Come si prepara? Come gestisce l'incontro? Chi interpreta la partner lo mette più o meno in difficoltà secondo come lui regge. Opzione 2: lei ha avuto una relazione con un altro. Come affronti la situazione? Se la relazione finisce, come succede, e come la gestisci se è lei a chiuderla? Opzione 3, spesso più facile per iniziare: aiutare un amico furioso la cui partner è stata vista abbracciare un altro. Il facilitatore può interpretare l'uomo arrabbiato, rendendo chiaro il rischio di violenza e il fatto che lui la giustifica; i volontari devono aiutarlo a gestire la rabbia e a prepararsi all'incontro con lei. Domande: quale intervento hai preferito? Saresti capace di reagire così? Su cosa devi lavorare per arrivarci? Fonte originale: uno spettacolo di teatro forum sulla maschilità di Parteciparte.", "tag": "violenza di genere; emozioni e benessere; potere e controllo"},
  {"nome": "Un fratello e un suo amico ti accusano di aver maltrattato sua sorella", "modulo": "WWP Giochi e strumenti teatrali – 5. Altre scene di teatro forum e role play", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori; ATTENZIONE: confronto teso sulla violenza agita", "obiettivo": "Allenarsi a sostenere argomenti contro la violenza di genere e a reggere un confronto teso senza minimizzare", "materiali": "Nessuno", "partecipanti": "Gruppo intero, con quattro volontari in scena", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Un volontario (A) esce dalla stanza e gli altri vengono istruiti. Un volontario (B) informa A che un fratello (C) e il suo amico (D) vogliono parlargli perché sostengono che è stato violento con la sorella di C. B esce, entrano C e D e accusano A, portando esempi concreti di comportamenti inaccettabili, preparati anche con l'aiuto del gruppo. C e D non sono affatto disposti a minimizzare. Come gestisce A la situazione? I partecipanti possono sostituire A, che deve reggere l'aggressività di C e D, oppure intervenire come il fratello che cerca di capire cosa fare quando un uomo che conosce maltratta sua sorella. L'esercizio sta a metà tra role play e teatro forum e spinge B, C e D ad argomentare contro la violenza di genere.", "tag": "violenza di genere; responsabilità; comunicazione"},
  {"nome": "Mettere in scena un’emozione gestita male", "modulo": "WWP Giochi e strumenti teatrali – 5. Altre scene di teatro forum e role play", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Allenarsi a gestire meglio un’emozione in una situazione reale e lavorare insieme sulla comprensione emotiva degli uomini", "materiali": "Nessuno", "partecipanti": "Gruppo intero che osserva e interviene", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Si chiede ai partecipanti una situazione, abbastanza semplice, in cui sono rimasti insoddisfatti di come hanno gestito un'emozione. Quando la storia è chiara, un volontario interpreta il personaggio che mette in difficoltà e gli altri partecipanti, a turno, provano a gestire meglio l'emozione e l'intera situazione, mostrando come farebbero loro.", "tag": "emozioni e benessere; responsabilità"},
  {"nome": "Il matrimonio e il funerale", "modulo": "WWP Giochi e strumenti teatrali – 5. Altre scene di teatro forum e role play", "durata": "10 minuti", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Allenarsi a negoziare un compromesso quando entrambe le parti hanno forti ragioni", "materiali": "Nessuno", "partecipanti": "Coppie", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "Due partecipanti scoprono di aver organizzato ciascuno un evento nello stesso luogo, lo stesso giorno, alla stessa ora: uno un funerale, l'altro un matrimonio. Il gestore ha affittato la sala a entrambi e non è raggiungibile; gli ospiti arriveranno tra meno di 10 minuti. Devono trovare una soluzione che soddisfi entrambi o almeno un compromesso. Si lavora in coppie per 10 minuti; ognuno deve tenere appassionatamente al proprio evento, e conviene prepararli bene a questo prima di iniziare.", "tag": "comunicazione; emozioni e benessere"},
  {"nome": "Vai in una scuola a parlare di violenza di genere", "modulo": "WWP Giochi e strumenti teatrali – 5. Altre scene di teatro forum e role play", "durata": "Non specificata", "target": "Uomini autori di violenza di genere in un programma di trattamento di gruppo; gestita da facilitatori", "obiettivo": "Mettere alla prova ciò che si è imparato nel programma spiegandolo ad altri", "materiali": "Nessuno", "partecipanti": "Gruppo intero; un volontario davanti agli altri", "fonte": "WWP EN – Scripting violence, rehearsing change. Giochi e strumenti teatrali per lavorare con autori di violenza di genere (Olivier Malcor, 2021)", "descrizione": "«Per il 25 novembre andrai in una scuola a parlare di violenza di genere.» Un volontario fa il suo intervento e gli altri partecipanti interpretano gli studenti: all'inizio non devono metterlo troppo in difficoltà, poi, se se la cava bene, possono alzare il livello e fargli notare le contraddizioni nel suo discorso. È l'occasione per spiegare ciò che si è imparato nel programma.", "tag": "violenza di genere; comunicazione; responsabilità"}
];
